import{f as o,o as a,c as i,a2 as d}from"./chunks/framework.BtbFyp-E.js";const A=JSON.parse('{"title":"Definición funcional del alcance — Nuevo sistema de gestión para cooperativas de servicios","description":"","frontmatter":{},"headers":[],"relativePath":"relevamiento/definicion-funcional-alcance.md","filePath":"relevamiento/definicion-funcional-alcance.md","lastUpdated":null}'),c={name:"relevamiento/definicion-funcional-alcance.md"};function r(t,e,s,l,n,u){return a(),i("div",null,[...e[0]||(e[0]=[d(`<h1 id="definicion-funcional-del-alcance-—-nuevo-sistema-de-gestion-para-cooperativas-de-servicios" tabindex="-1">Definición funcional del alcance — Nuevo sistema de gestión para cooperativas de servicios <a class="header-anchor" href="#definicion-funcional-del-alcance-—-nuevo-sistema-de-gestion-para-cooperativas-de-servicios" aria-label="Permalink to &quot;Definición funcional del alcance — Nuevo sistema de gestión para cooperativas de servicios&quot;">​</a></h1><p>Versión: 0.1 (borrador para validar) Fecha: 3/11/2026 Base: relevamiento directo de Procoop 10.4.6.722 (base DEMO de la Cooperativa Eléctrica Laguna Larga) y modelo de datos extraído de <code>CapaDatos.dll</code>.</p><h2 id="_0-como-leer-este-documento" tabindex="-1">0. Cómo leer este documento <a class="header-anchor" href="#_0-como-leer-este-documento" aria-label="Permalink to &quot;0. Cómo leer este documento&quot;">​</a></h2><p><strong>Objetivo:</strong> reproducir las capacidades funcionales de Procoop en un sistema nuevo, moderno (web/SaaS) y mejor diseñado, sin copiar su código ni su interfaz.</p><p>Cada función indica en qué evidencia se apoya:</p><table tabindex="0"><thead><tr><th>Marca</th><th>Significado</th></tr></thead><tbody><tr><td><strong>[P]</strong></td><td>Pantalla abierta y observada en Procoop (con captura en <code>capturas/</code>).</td></tr><tr><td><strong>[M]</strong></td><td>Opción vista en el menú de Procoop, sin abrir la pantalla.</td></tr><tr><td><strong>[T]</strong></td><td>Tabla del modelo de datos de <code>CapaDatos.dll</code>. Su significado se deduce del nombre y de sus relaciones; hay que confirmarlo con la base o el código.</td></tr><tr><td><strong>[I]</strong></td><td>Inferido a partir de lo anterior. Validar con la cooperativa.</td></tr><tr><td><strong>Mejora</strong></td><td>Propuesta de modernización respecto de Procoop.</td></tr></tbody></table><p><strong>Prioridad de cada módulo:</strong></p><table tabindex="0"><thead><tr><th>Prioridad</th><th>Significado</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Imprescindible para el paralelo con la cooperativa piloto: facturar, cobrar y gestionar mora de energía y gas.</td></tr><tr><td><strong>B</strong></td><td>Necesario para reemplazar Procoop completamente (by pass).</td></tr><tr><td><strong>C</strong></td><td>Complementario; se puede diferir.</td></tr></tbody></table><p>Las prioridades son una propuesta y deben acordarse con la cooperativa.</p><p><strong>Escala de lo relevado:</strong></p><ul><li><strong>Funciones:</strong> 9 módulos de menú con unas 150 funciones.</li><li><strong>Datos:</strong> 667 tablas de negocio, más 39 de la app móvil, 31 del portal web y 21 de telemedición.</li><li><strong>Volumen de facturación:</strong> en la base DEMO hay unos 12.500 comprobantes por emisión mensual.</li></ul><hr><h2 id="_1-mapa-general-de-modulos" tabindex="-1">1. Mapa general de módulos <a class="header-anchor" href="#_1-mapa-general-de-modulos" aria-label="Permalink to &quot;1. Mapa general de módulos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Módulo</th><th>Prioridad</th><th>Origen en Procoop</th></tr></thead><tbody><tr><td>1</td><td>Plataforma, seguridad y auditoría</td><td>A</td><td>Configuración &gt; General</td></tr><tr><td>2</td><td>Parámetros y tablas maestras</td><td>A</td><td>Configuración &gt; Tablas y Parámetros</td></tr><tr><td>3</td><td>Personas, titulares y cuentas</td><td>A</td><td>Servicios a Titulares &gt; Titulares</td></tr><tr><td>4</td><td>Catálogo de servicios, categorías y conexiones</td><td>A</td><td>Tablas de Facturación, fichas de servicio</td></tr><tr><td>5</td><td>Medidores y equipos de medición</td><td>A</td><td>Ficha de servicio &gt; Medidor</td></tr><tr><td>6</td><td>Lecturas, consumos y telemedición</td><td>A</td><td>Servicios a Titulares &gt; Consumos, Operaciones &gt; Telemed</td></tr><tr><td>7</td><td>Cuadros tarifarios y motor de cálculo</td><td>A</td><td>Tablas &gt; Cuadros Tarifarios, Impuestos, Cargos</td></tr><tr><td>8</td><td>Facturación de servicios y comprobantes electrónicos</td><td>A</td><td>Ventas y Facturación</td></tr><tr><td>9</td><td>Cuenta corriente del titular</td><td>A</td><td>Transversal (deuda vencida, comprobantes)</td></tr><tr><td>10</td><td>Cobranza: cajas, medios de pago y entes recaudadores</td><td>A</td><td>Cobranza, Tablas de Cobranzas</td></tr><tr><td>11</td><td>Gestión de mora y corte</td><td>A</td><td>Crédito y Gestión de Mora</td></tr><tr><td>12</td><td>Financiación y planes de pago</td><td>B</td><td>Crédito &gt; Financiaciones</td></tr><tr><td>13</td><td>Ventas, presupuestos y punto de venta</td><td>B</td><td>Presupuestos, Venta de Productos</td></tr><tr><td>14</td><td>Técnica: factibilidades, órdenes de trabajo y reclamos</td><td>B</td><td>Operaciones &gt; Técnica</td></tr><tr><td>15</td><td>Redes e infraestructura (GIS)</td><td>C</td><td>Tablas <code>REDES_*</code>, coordenadas</td></tr><tr><td>16</td><td>Compras y proveedores</td><td>B</td><td>Compras y Stock &gt; Gestión de Compras</td></tr><tr><td>17</td><td>Stock, bienes de uso, RMA y fabricación</td><td>B</td><td>Compras y Stock &gt; Stock, RMA</td></tr><tr><td>18</td><td>Tesorería y bancos</td><td>B</td><td>Tesorería</td></tr><tr><td>19</td><td>Contabilidad</td><td>B</td><td>Contabilidad</td></tr><tr><td>20</td><td>Sueldos y personal</td><td>C</td><td>Sueldos</td></tr><tr><td>21</td><td>Atención: mesa de entradas, turnero, comunicaciones</td><td>B</td><td>Herramientas</td></tr><tr><td>22</td><td>Actividades y tareas internas</td><td>C</td><td>Herramientas &gt; Actividades</td></tr><tr><td>23</td><td>Traslados y flota</td><td>C</td><td>Herramientas &gt; Traslados</td></tr><tr><td>24</td><td>Gestión institucional (asociados, capital, asambleas)</td><td>C</td><td>Tablas <code>SOCIOS</code>, <code>CAPITAL</code>, <code>ACTAS</code>, <code>CONSEJO</code></td></tr><tr><td>25</td><td>Servicios sociales y otros servicios</td><td>C</td><td>Planes de Vivienda, <code>AMBULANC</code>, <code>MEDICOS</code></td></tr><tr><td>26</td><td>Autogestión del socio (portal y app)</td><td>B</td><td>Procoop WEB / CoopOnline, <code>CapaDatos.PWeb</code></td></tr><tr><td>27</td><td>App móvil de campo</td><td>B</td><td><code>CapaDatos.PMovil</code></td></tr><tr><td>28</td><td>Reportes, tableros y exportaciones</td><td>B</td><td>Reportes, Tablero de Control, <code>TABLAS_POWERBI</code></td></tr><tr><td>29</td><td>Integraciones externas</td><td>A/B</td><td>ARCA, EPEC, ENARGAS, RED LINK, SIRO, Pagos360, bancos</td></tr></tbody></table><hr><h2 id="_2-modulo-1-—-plataforma-seguridad-y-auditoria-a" tabindex="-1">2. Módulo 1 — Plataforma, seguridad y auditoría (A) <a class="header-anchor" href="#_2-modulo-1-—-plataforma-seguridad-y-auditoria-a" aria-label="Permalink to &quot;2. Módulo 1 — Plataforma, seguridad y auditoría (A)&quot;">​</a></h2><p><strong>Objetivo:</strong> controlar quién entra, qué puede hacer y dejar trazabilidad de todo.</p><h3 id="funciones" tabindex="-1">Funciones <a class="header-anchor" href="#funciones" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Usuarios</strong> [M] (Configuración &gt; Administración de Usuarios)</p><ul><li>Alta, baja y modificación de usuarios.</li><li>Asignación del usuario a un área y a uno o más depósitos.</li><li>Datos propios de cada usuario: alias y punto de venta asignado. En la sesión DEMO se ve &quot;Usuario COOPERATIVA – Alias COOPONLINE – Punto de Venta 0097&quot;.</li><li>Tablas: <code>USERS</code>, <code>USERS_AREA</code>, <code>USERS_DEPOSITO</code>, <code>USERS_EXTRAS</code>, <code>CLAVES</code> [T].</li></ul><p><strong>Perfiles</strong> [M] (Administración de Perfiles)</p><ul><li>Permisos por opción de menú y por tabla.</li><li>Tablas: <code>PERFILES</code>, <code>PERFILES_TABLAS</code>, <code>MENUSYS</code>, <code>MENUVAL</code>, <code>MODULOS</code> [T].</li></ul><p><strong>Auditoría</strong> [M] (Auditoría de Logueo)</p><ul><li>Registro de ingresos al sistema.</li><li>Auditoría de cambios en los datos.</li><li>Tablas: <code>AUDITO</code>, <code>AUDITORIA</code>, <code>INFO_AUD</code>, <code>AUDIT_MAIL</code>, <code>AUDIT_IA</code> [T]. Existe una auditoría específica de IA, lo que indica que Procoop ya incorpora alguna función de IA.</li></ul><p><strong>Autorización de Operaciones</strong> [M]</p><ul><li>Operaciones que requieren la aprobación de un supervisor.</li><li>Tabla: <code>AUTORIZACIONES</code> [T].</li></ul><p><strong>Bloqueos</strong></p><ul><li>Bloqueo de registros mientras se editan: <code>BLOQUEO_FILAS</code> [T].</li><li>Modo &quot;Sólo LECTURA&quot; en las fichas [P].</li></ul><p><strong>Copia de seguridad, Base de Datos y Actualizar</strong> [M]</p><ul><li>En Procoop son tareas de una instalación local.</li><li><strong>Mejora:</strong> en un SaaS estas tareas pasan a ser responsabilidad de la plataforma y no del usuario.</li></ul><p><strong>Firma digital y electrónica de documentos</strong></p><ul><li>Tablas: <code>FIRMADIGITAL*</code>, <code>FIRMASELECTRONICAS*</code> [T].</li></ul><p><strong>API para terceros</strong></p><ul><li>Claves y usuarios de servicios web asociados a cuentas: <code>WS_KEYS</code>, <code>WS_USERS</code>, <code>WS_USERS_ACCOUNTS</code> [T].</li></ul><p><strong>Configuración general del sistema</strong></p><ul><li>Tablas: <code>ConfiguracionesSistema</code>, <code>INFO_SYS</code> [T].</li></ul><h3 id="mejoras-propuestas" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Login moderno con OpenIddict, 2FA y recuperación de contraseña.</li><li>Roles con permisos por acción (ver, crear, modificar, anular, aprobar) y no solo por menú.</li><li>Auditoría inmutable que guarde el valor anterior y el nuevo de cada cambio.</li><li>Aprobaciones configurables con un flujo de dos pasos: quien crea no puede aprobar.</li><li>Multi-cooperativa: una base por cooperativa, según la arquitectura definida.</li></ul><hr><h2 id="_3-modulo-2-—-parametros-y-tablas-maestras-a" tabindex="-1">3. Módulo 2 — Parámetros y tablas maestras (A) <a class="header-anchor" href="#_3-modulo-2-—-parametros-y-tablas-maestras-a" aria-label="Permalink to &quot;3. Módulo 2 — Parámetros y tablas maestras (A)&quot;">​</a></h2><p>Procoop organiza su parametrización en &quot;Tablas del sistema&quot; por dominio [P]: Generales, Titulares, Cobranzas, Técnica, Facturación, Gestión de Mora, Telefonía, Viviendas, Sueldos, Tesorería, Contabilidad, Compras, SMS, Actividades y Herramientas. Además tiene Parámetros del Sistema y Parámetros Externos [M].</p><h3 id="geografia-y-ubicacion-t" tabindex="-1">Geografía y ubicación [T] <a class="header-anchor" href="#geografia-y-ubicacion-t" aria-label="Permalink to &quot;Geografía y ubicación [T]&quot;">​</a></h3><ul><li>Ubicación administrativa: <code>PAISES</code>, <code>PROVINC</code>, <code>LOCALIDA</code>, <code>POSTALES</code>, <code>DEPARTA</code>, <code>DISTRITO_SECCION</code>.</li><li>Domicilios: <code>CALLES</code>, <code>BARRIOS</code>.</li><li>Organización del territorio para lectura y operación: <code>ZONAS</code>, <code>SECCION</code>.</li><li>Catastro (en la ficha [P]): Cod / Sec / Man / Par / PH / Lote.</li><li>Coordenadas latitud y longitud del servicio [P]. Por ejemplo: −31.769237, −63.790995.</li></ul><h3 id="calendario-t" tabindex="-1">Calendario [T] <a class="header-anchor" href="#calendario-t" aria-label="Permalink to &quot;Calendario [T]&quot;">​</a></h3><ul><li><code>CALENDARIO</code>, <code>CALENDARIO_TIPO</code>, <code>FERIADOS</code>. Se usan para vencimientos y días hábiles.</li></ul><h3 id="indices-economicos-t" tabindex="-1">Índices económicos [T] <a class="header-anchor" href="#indices-economicos-t" aria-label="Permalink to &quot;Índices económicos [T]&quot;">​</a></h3><ul><li><code>INFLACIO</code>, <code>TABINFL</code> (inflación).</li><li><code>COT_DOL</code> (cotización del dólar).</li><li><code>TABMORA</code>, <code>INDICESMORA</code> (índices de recargo por mora).</li></ul><h3 id="tablas-fiscales-t" tabindex="-1">Tablas fiscales [T] <a class="header-anchor" href="#tablas-fiscales-t" aria-label="Permalink to &quot;Tablas fiscales [T]&quot;">​</a></h3><ul><li>IVA: <code>SITIVA</code> (situación frente al IVA), <code>ALI_IVA*</code> (alícuotas de IVA).</li><li>Ingresos Brutos: <code>SITIBR</code>, <code>ALI_IBR*</code>.</li><li><code>IIBB_LUA</code>: padrón de Ingresos Brutos.</li><li><code>CVPIIBB</code>: código de validación provincial.</li></ul><h3 id="tablas-genericas-t" tabindex="-1">Tablas genéricas [T] <a class="header-anchor" href="#tablas-genericas-t" aria-label="Permalink to &quot;Tablas genéricas [T]&quot;">​</a></h3><ul><li><code>TABLAS</code>, <code>TIPO_TAB</code>, <code>GRUTAB</code>, <code>GRUPTAB</code>, <code>ESTATAB</code>, <code>COMBOS</code>.</li></ul><h3 id="mejoras-propuestas-1" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-1" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Un editor de tablas maestras uniforme, con búsqueda y vigencias.</li><li>Importación de padrones (calles, IIBB) por archivo.</li><li>Versionado de parámetros con fecha de vigencia, en lugar de pisar el valor anterior.</li></ul><hr><h2 id="_4-modulo-3-—-personas-titulares-y-cuentas-a" tabindex="-1">4. Módulo 3 — Personas, titulares y cuentas (A) <a class="header-anchor" href="#_4-modulo-3-—-personas-titulares-y-cuentas-a" aria-label="Permalink to &quot;4. Módulo 3 — Personas, titulares y cuentas (A)&quot;">​</a></h2><p><strong>Objetivo:</strong> registrar quién es el cliente, qué cuentas tiene y dónde se presta cada servicio.</p><h3 id="jerarquia-observada-p" tabindex="-1">Jerarquía observada [P] <a class="header-anchor" href="#jerarquia-observada-p" aria-label="Permalink to &quot;Jerarquía observada [P]&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Persona  (física o jurídica: nombre, documento/CUIT, contacto)</span></span>
<span class="line"><span> └─ Titular  (N° de titular, NIP, activo)</span></span>
<span class="line"><span>     └─ Cuenta  (N°, domicilio postal, condición de IVA)</span></span>
<span class="line"><span>         └─ Grupo de Factura (G.F.)   → define qué servicios salen juntos en un comprobante</span></span>
<span class="line"><span>             └─ Servicio contratado  (tipo + medidor + estado + categoría)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Ejemplo real: el titular 1 es la Municipalidad de Laguna Larga, con varias cuentas. Una de ellas tiene ENERGÍA ELÉCTRICA (alumbrado público, conectado) y GAS NATURAL (de baja).</p><h3 id="funciones-1" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-1" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Administración de Titulares</strong> [P]</p><ul><li>Búsqueda por Persona, Calle, Documento, Titular, rango de titulares (Entre/y) y Cuenta.</li><li>Opciones de búsqueda &quot;Consultar domicilio de servicios&quot; y &quot;Solo cuentas con servicios activos&quot;.</li><li>Acciones: Agregar, Modificar, Baja, Consultar, Imprimir y Operación.</li><li>Grilla: N° de titular, Nombre, Documento, NIP y Activo.</li></ul><p><strong>Administración de Personas</strong> [M]</p><ul><li>Personas separadas de los titulares: una persona puede ser titular, garante, profesional o responsable.</li></ul><p><strong>Ficha del titular</strong> [P]</p><ul><li>Pestañas: Datos Persona, Titular, Cuentas y Servicios.</li><li>Árbol de cuentas, grupos de factura y servicios.</li><li>Panel de Trámites de la Cuenta.</li><li>Observaciones con fecha, título y un indicador de <strong>Bloqueo</strong>.</li><li>Adjuntos.</li><li>Contacto directo por WhatsApp y e-mail.</li></ul><p><strong>Consultas e Informes de titulares</strong> [M].</p><p><strong>Datos de cada cuenta</strong> [P]</p><ul><li>Domicilio, condición de IVA (Consumidor Final, Exento…) y descripción.</li></ul><p><strong>Relaciones</strong> [T]</p><ul><li><code>VINCULOS</code> (vínculos entre personas).</li><li><code>RESPONSA</code> (responsables y garantes).</li><li><code>RELACION_ENTIDADES</code>.</li></ul><p><strong>Datos personales</strong> [T]</p><ul><li><code>EST_CIVIL</code>, <code>OCUPACIO</code>.</li><li><code>PERSONAS_EXTRAS</code> (campos adicionales configurables).</li></ul><p><strong>Inmuebles</strong> [T]</p><ul><li><code>PROPIEDA</code>, <code>PROPIESER</code> (propiedad y servicio), <code>USOINM</code>, <code>ESTINM</code>.</li><li>Ítems de propiedad con valores (<code>PROPIEITEMS*</code>).</li></ul><p><strong>Adhesiones y beneficios</strong> [T]</p><ul><li><code>ADHSOC</code> (adhesiones del socio, por ejemplo factura por mail o débito automático).</li><li><code>BENSOC</code> (beneficios o tarifa social). Existe una carpeta <code>tarifasocial</code> entre los binarios.</li></ul><p><strong>Trámites</strong> [T]</p><ul><li><code>TRAMITES</code>, <code>TRAMITES_ACCIONES</code>, <code>PTRAMITES</code>, <code>REQUISITOS</code>, <code>REQUISITOS_ITEMS</code>, <code>EXPEDIENTES</code>, <code>EXPEDIENTES_TRAM</code>.</li><li>Ligado a &quot;Procoop WEB &gt; Requisitos y Trámites&quot; [M].</li></ul><p><strong>Documentación</strong> [T]</p><ul><li><code>ADJUNTOS</code>, <code>ARCHIVOS</code>, <code>DOCUMENT</code>, <code>NOTA_SUM</code>.</li></ul><p><strong>Historia</strong> [T]</p><ul><li><code>SUMSOC_HST</code>, <code>SERSOC_HST</code>: históricos de cuentas y servicios.</li><li><code>HISBLOQ</code>, <code>CAUBLOQ</code>: historial de bloqueos y sus causas.</li></ul><h3 id="tablas-nucleo-t" tabindex="-1">Tablas núcleo [T] <a class="header-anchor" href="#tablas-nucleo-t" aria-label="Permalink to &quot;Tablas núcleo [T]&quot;">​</a></h3><ul><li><code>PERSONAS</code>: persona.</li><li><code>SOCIOS</code>: titular o asociado.</li><li><code>SUMSOC</code>: suministro o cuenta del socio.</li><li><code>SERSOC</code>: servicio contratado. Se relaciona con <code>ACTAFIP</code>, <code>SERSOC_PRODUCTOS</code>, <code>SERSOC_REDES</code> y <code>SERSOC_DEMANDASXPERIODO</code>.</li></ul><h3 id="mejoras-propuestas-2" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-2" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Ficha 360°:</strong> en una sola vista, datos, cuentas, servicios, saldo, últimas facturas, pagos, reclamos, trámites y comunicaciones.</li><li><strong>Validaciones:</strong> CUIT/CUIL con dígito verificador y consulta al padrón de ARCA.</li><li><strong>Domicilios normalizados:</strong> mapa en el alta y geocodificación.</li><li><strong>Bloqueos tipados:</strong> que el bloqueo indique qué impide (facturar, cobrar, dar de baja) en vez de ser una observación libre.</li><li><strong>Cambio de titularidad:</strong> circuito explícito que preserve la deuda y la historia.</li></ul><hr><h2 id="_5-modulo-4-—-catalogo-de-servicios-categorias-y-conexiones-a" tabindex="-1">5. Módulo 4 — Catálogo de servicios, categorías y conexiones (A) <a class="header-anchor" href="#_5-modulo-4-—-catalogo-de-servicios-categorias-y-conexiones-a" aria-label="Permalink to &quot;5. Módulo 4 — Catálogo de servicios, categorías y conexiones (A)&quot;">​</a></h2><p><strong>Objetivo:</strong> definir qué servicios presta la cooperativa y cómo se clasifica cada suministro.</p><h3 id="tipos-de-servicio" tabindex="-1">Tipos de servicio <a class="header-anchor" href="#tipos-de-servicio" aria-label="Permalink to &quot;Tipos de servicio&quot;">​</a></h3><p>Vistos en la base [P]: ENERGÍA ELÉCTRICA y GAS NATURAL. En el modelo [T] aparecen además:</p><ul><li>Telefonía: <code>TEL_*</code>, <code>TARTEL</code>, <code>SERTEL</code>.</li><li>Internet: <code>INTERNET</code>, <code>MIKROTIK</code>, <code>MODEMS</code>, <code>SERVINT</code>.</li><li>Agua: [I].</li><li>Servicios sociales: <code>AMBULANC</code>, <code>MEDICOS</code>, <code>INTERNAC</code>.</li><li>Vivienda: <code>VIVIENDAS</code>, <code>VIV_*</code>.</li></ul><h3 id="funciones-2" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-2" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Definición del servicio</strong> [T][P]</p><ul><li>Tablas: <code>SERVICIO</code>, <code>TIP_SERVI</code>, <code>CLASESER</code>.</li><li>&quot;Clase de servicio&quot; se ve en la ficha [P], por ejemplo &quot;4 TASA HOSPITAL MUNICIPAL&quot;.</li><li>Tablas relacionadas a Facturación &gt; Clases de Servicios [M].</li></ul><p><strong>Categorías tarifarias</strong> [P][T]</p><ul><li>Ejemplo: &quot;19 ALUMBRADO PÚBLICO&quot;.</li><li>Tablas: <code>CATE_SER</code>, <code>CATE_SER_COEFICIENTES</code>, <code>CATE_SER_EXTRAS</code>, <code>CATTARIF</code>.</li><li>Grupos de Categorías [M], <code>GRP_CAT</code>.</li><li>Recategorización automática, con la marca &quot;No aplica recategorización&quot; [P].</li></ul><p><strong>Estados del servicio</strong> [P][T]</p><ul><li>Ejemplos: CONECTADO, baja.</li><li>Se registra la fecha del último estado.</li><li>Tablas: <code>ESTASER</code>, <code>OBSESTAD</code>, <code>RESESTAD</code>, <code>CERESTAD</code>.</li></ul><p><strong>Datos del servicio contratado</strong> [P]</p><ul><li>Domicilio, referencia, catastro, DD JJ, contrato, inmueble y GIS.</li><li>Actividad (con relación a Actividades ARCA [M]) y garante.</li><li>Grupo de factura y fechas de alta y baja.</li><li>Profesional instalador (<code>PROFESIO</code> [T]), número y vencimiento de certificado, e Id de cliente.</li><li>Marcas Provisorio / Cobrar provisorio y &quot;No Facturar&quot;.</li><li>&quot;Alta desde CoopOnline&quot;, es decir, alta iniciada por el portal.</li><li>Id de factibilidad, matrícula y coordenadas.</li></ul><p><strong>Demanda</strong> [P][T]</p><ul><li>Demanda en pico y fuera de pico, para tarifas con potencia contratada: <code>SERSOC_DEMANDASXPERIODO</code>.</li></ul><p><strong>Conexión</strong> [T]</p><ul><li><code>CONEXION</code>, <code>CONE_BONIF</code> (bonificación de conexión).</li></ul><p><strong>Productos y conceptos facturables por servicio</strong> [M][T]</p><ul><li>Servicios para Facturar, Productos.</li><li>Tablas: <code>PROD_SER</code>, <code>PROD_SER_REC_DES</code> (recargos y descuentos), <code>PROD_SER_RET</code> (retenciones), <code>PROD_SER_UBICACION</code>.</li></ul><p><strong>Altas y Bajas Automáticas de Servicios</strong> [M]</p><ul><li>Tabla: <code>ALTASEAU</code> [T].</li></ul><p><strong>Servicios no facturables</strong> [T]</p><ul><li><code>SUMNOFAC</code>.</li></ul><p><strong>Gas</strong> [T][M]</p><ul><li>Artefactos del suministro: <code>ARTEFACTO</code>, <code>ARTEFSUMS</code>, <code>HIS_ARTEFSUMS</code>.</li><li>Factor de corrección y PCS (poder calorífico): <code>CORREGAS</code>, <code>PRCAGAS</code>.</li><li>Información para ENARGAS: <code>ENGAS_CANTMESES</code> y la carpeta <code>ENARGAS</code>.</li><li>Opciones de Gas [M].</li></ul><p><strong>Prepago</strong> [M][T]</p><ul><li>Configuración de Prepaga: <code>PREPAGA</code>.</li><li>En la base hay facturas de energía en modalidad prepaga [P].</li></ul><h3 id="mejoras-propuestas-3" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-3" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>El catálogo de servicios se configura sin programar: atributos por servicio, estados y transiciones permitidas.</li><li>Historial de categoría por vigencia, para facturar cada período con la categoría que correspondía.</li><li>Plantillas de servicio reutilizables entre cooperativas.</li></ul><hr><h2 id="_6-modulo-5-—-medidores-y-equipos-de-medicion-a" tabindex="-1">6. Módulo 5 — Medidores y equipos de medición (A) <a class="header-anchor" href="#_6-modulo-5-—-medidores-y-equipos-de-medicion-a" aria-label="Permalink to &quot;6. Módulo 5 — Medidores y equipos de medición (A)&quot;">​</a></h2><h3 id="funciones-p-t" tabindex="-1">Funciones [P][T] <a class="header-anchor" href="#funciones-p-t" aria-label="Permalink to &quot;Funciones [P][T]&quot;">​</a></h3><p><strong>Ficha del medidor</strong> [P]</p><ul><li>Modelo (ej. 1 Galileo), Id del medidor (ej. 5884320) y tipo (MONOFÁSICO).</li><li>Cantidad de dígitos, factor de multiplicación (1,0000) y HP.</li><li>Unidades bonificadas.</li><li>Medidor testigo.</li><li>Observaciones del medidor.</li><li>Marca &quot;Lectura recibida con factor de multiplicación&quot;.</li></ul><p><strong>Tablas</strong> [T]</p><ul><li><code>MEDSOC</code> (medidor instalado en el servicio) y <code>HIS_MEDSOC</code> (historial de colocación y retiro).</li><li><code>MARMED</code> (marcas), <code>TIPMED</code> (tipos), <code>ESPE_MED</code> (especificaciones).</li><li><code>MEDIDORP</code>, <code>MED_TESTIGO</code>, <code>OBSMED</code>.</li><li>Testigos de consumo: <code>CONS_SER_TESTIGO</code>.</li></ul><p><strong>Cambio de medidor</strong></p><ul><li>Las observaciones de los servicios registran órdenes de trabajo del tipo &quot;CAMBIO DE NUMERO&quot; [P].</li><li>El cambio de medidor genera historia y lectura de retiro y colocación [I].</li></ul><h3 id="mejoras-propuestas-4" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-4" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Inventario de medidores integrado con stock: estado, ubicación y número de serie.</li><li>Cambio de medidor guiado, con lectura final del medidor retirado e inicial del nuevo, y con el consumo partido en el período.</li></ul><hr><h2 id="_7-modulo-6-—-lecturas-consumos-y-telemedicion-a" tabindex="-1">7. Módulo 6 — Lecturas, consumos y telemedición (A) <a class="header-anchor" href="#_7-modulo-6-—-lecturas-consumos-y-telemedicion-a" aria-label="Permalink to &quot;7. Módulo 6 — Lecturas, consumos y telemedición (A)&quot;">​</a></h2><h3 id="funciones-3" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-3" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Registro manual de Lecturas</strong> [P]</p><ul><li>Encabezado: fecha, período (mes y año), servicio, titular, cuenta, observación y marca &quot;Consumo Estimado&quot;.</li><li>Grilla: servicio, fecha anterior, lectura anterior, consumo anterior, lectura actual, consumo actual, tipo de energía y concepto. El botón &quot;Correcto&quot; confirma.</li><li>Datos del servicio: categoría, característica, N° de medidor, dígitos, domicilio, factor de multiplicación, Cos φ (factor de potencia) e Indicado.</li><li>Historial de consumos: categoría, medidor, fechas y lecturas, días, consumo, período y factura.</li><li>Botón &quot;Consulta de consumos&quot;.</li></ul><p><strong>Ruta de lectura</strong> [P][T]</p><ul><li>Zona, Sector y Recorrido de cada servicio. Ejemplo: zona 30, sector 1, recorrido 250.</li><li>Tablas: <code>CONNRUTA</code>, <code>CONNZONA</code>.</li></ul><p><strong>Lectura en campo</strong> [T]</p><ul><li>App móvil (<code>CapaDatos.PMovil</code>, <code>MOVIL</code>, <code>VARIABLE_PMOVIL</code>).</li><li>Horas de los lectores: <code>SU_HORAS_LECTOR</code>.</li></ul><p><strong>Telemedición</strong> [M][T]</p><ul><li>Menús: Telemed &gt; Administración, Informes y Configuración.</li><li>Tablas: <code>TELEMEDICION</code>, <code>TELEMED_COMM</code>, <code>LEC_MEDTEL</code>, <code>AUDITORIA_TELEMEDICION</code>, y el namespace <code>CapaDatos.Telemed.Telemedicion</code>.</li></ul><p><strong>Consumos</strong> [T]</p><ul><li><code>CONS_SER</code> (consumo por servicio y período), <code>CONSUMOP</code>, <code>DST_CONSUMO</code> (distribución del consumo).</li><li>Información técnica por banda horaria [I]: <code>INFOCTD</code>, <code>INFOCTN</code>, <code>INFOCTG</code>.</li><li>Bandas: <code>BANDAS</code>.</li></ul><p><strong>Otras opciones</strong> [M]</p><ul><li>Opciones de consumos, Informes de Consumos, Opciones de Telefonía (consumo telefónico).</li></ul><p><strong>Control de consumos</strong> [T][I]</p><ul><li><code>CTRLCNC</code>: control de consumo fuera de rango.</li></ul><h3 id="mejoras-propuestas-5" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-5" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>App de lectura offline:</strong> foto obligatoria cuando el consumo está fuera de rango, GPS, novedades codificadas y sincronización.</li><li><strong>Validación automática:</strong> consumo cero, negativo o fuera de un rango histórico configurable. Bandeja de excepciones antes de facturar.</li><li><strong>Estimación configurable:</strong> promedio de los últimos N períodos o del mismo período del año anterior.</li><li><strong>Telemedición:</strong> importación estándar de lecturas desde AMI/MDM.</li></ul><hr><h2 id="_8-modulo-7-—-cuadros-tarifarios-y-motor-de-calculo-a" tabindex="-1">8. Módulo 7 — Cuadros tarifarios y motor de cálculo (A) <a class="header-anchor" href="#_8-modulo-7-—-cuadros-tarifarios-y-motor-de-calculo-a" aria-label="Permalink to &quot;8. Módulo 7 — Cuadros tarifarios y motor de cálculo (A)&quot;">​</a></h2><p><strong>Objetivo:</strong> el precio de cada concepto según el servicio, la categoría y la vigencia.</p><h3 id="funciones-4" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-4" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Administración de Cuadros Tarifarios</strong> [P]</p><ul><li>Listado: Descripción, Código, Usuario, vigencia Desde y Hasta. Acciones: Nuevo, Modificar, Imprimir.</li><li>Los cuadros se versionan por vigencia y se nombran por mes o por norma. Ejemplos: &quot;ABRIL 2026&quot;, &quot;196/2023 GAS&quot;, &quot;ANTES CAMBIO FODEP 10%&quot;, &quot;ANTES DE RG 129 MARZO&quot;.</li></ul><p><strong>Detalle histórico por cuadro</strong> [T]</p><ul><li><code>CUADROS</code> se relaciona con: <ul><li><code>HIS_CATTARIF</code>: tarifa por categoría.</li><li><code>HIS_CATE_SER</code> y <code>HIS_CATE_SER_EXTRAS</code>: valores por categoría de servicio.</li><li><code>HIS_IMPUESTO</code>: alícuotas de impuestos.</li><li><code>HIS_CARGOS_ADICIONALES</code>: cargos.</li><li><code>HIS_PROD_SER</code>: precios de productos y servicios.</li><li><code>HIS_SERVICIO</code> y <code>HIS_SERVICIO_EXTRAS</code>.</li><li><code>HIS_TAR_ADHE</code>: tarifas de adhesiones.</li><li><code>ITEMSFAC_EXTRAS</code>.</li></ul></li><li><strong>Conclusión:</strong> cada cuadro guarda una foto completa de precios e impuestos vigentes, y cada factura queda ligada al cuadro que la valorizó.</li></ul><p><strong>Cargos e impuestos</strong> [M][T]</p><ul><li>Cargos Adicionales: <code>CARGOS_ADICIONALES</code>.</li><li>Impuestos: <code>IMPUESTO</code>, <code>IMPUESTOS_X_CAT</code>.</li><li>Conceptos para Cálculo de Intereses: <code>CONCEPTOS_INT</code>.</li><li>Recargos: <code>RECARGOS</code>.</li></ul><p><strong>Coeficientes y factores</strong> [T]</p><ul><li><code>FACTOR_CAL</code>, <code>CATE_SER_COEFICIENTES</code>, <code>BANDAS</code>.</li></ul><p><strong>Bonificaciones</strong> [T]</p><ul><li><code>GRATIS</code>, <code>TEMPMODIFBONIF</code>, <code>CONE_BONIF</code>.</li></ul><p><strong>Componentes de la factura observados</strong> [P]</p><ul><li>Energía: kWh × precio unitario. Ejemplo: 18,30 × $270,33.</li><li>Tasas de terceros: alumbrado público, Decreto 2298/00 (0,40 %), RG 27/2015, entre otras.</li><li>IVA y otros impuestos.</li></ul><h3 id="mejoras-propuestas-6" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-6" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Motor de tarifas declarativo:</strong><ul><li>Cargo fijo.</li><li>Cargo variable por escalones o bloques.</li><li>Cargo por demanda (potencia).</li><li>Mínimos.</li><li>Tasas como porcentaje o importe fijo, con su base imponible.</li><li>Topes y bonificaciones.</li></ul></li><li><strong>Simulador:</strong> antes de publicar un cuadro nuevo, recalcular un período sobre todo el padrón y comparar contra el cuadro anterior.</li><li><strong>Aprobación:</strong> circuito de doble firma, quien carga y quien aprueba.</li><li><strong>Trazabilidad normativa:</strong> cada cuadro se vincula a la resolución (ERSeP, ENARGAS, municipal) con el PDF adjunto.</li></ul><hr><h2 id="_9-modulo-8-—-facturacion-de-servicios-y-comprobantes-electronicos-a" tabindex="-1">9. Módulo 8 — Facturación de servicios y comprobantes electrónicos (A) <a class="header-anchor" href="#_9-modulo-8-—-facturacion-de-servicios-y-comprobantes-electronicos-a" aria-label="Permalink to &quot;9. Módulo 8 — Facturación de servicios y comprobantes electrónicos (A)&quot;">​</a></h2><h3 id="funciones-5" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-5" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Administración de Comprobantes</strong> [P]</p><ul><li>Navegación por rangos semanales de fecha de emisión, con criterio de agrupación configurable.</li><li>Búsqueda libre y filtros.</li><li>Grilla: fecha, comprobante (tipo + PV + N°, ej. <code>Spb 0022-00128032</code>), cuenta, titular, nombre, total y anulada, con fila de totales.</li><li>Acciones: Agregar, Consultar, Elemento, Operaciones, Imprimir y Vista.</li><li>Volumen: 12.499 comprobantes en una semana, por $629.206.692,60 [P].</li></ul><p><strong>Detalle del comprobante</strong> (&quot;Registro de Facturas Manuales&quot;) [P]</p><ul><li>Cabecera: <ul><li>Tipo (ej. &quot;97 - LIQ. DE SERV. B&quot;), punto de venta, número y letra, fecha.</li><li>Cuenta y domicilio, titular y vendedor.</li><li>Cuota (ej. PR = PREPAGO), depósito y período.</li><li><strong>Deuda vencida</strong> del titular y marca &quot;Registrar Pago&quot;.</li></ul></li><li>Renglones: descripción, cantidad, precio unitario, impuestos, IVA y neto.</li><li>Totales: sub neto, descuento %, neto, percepciones, IVA, otros impuestos y total.</li><li><strong>Hasta 4 vencimientos</strong>, cada uno con su fecha y su total con recargo.</li><li>&quot;Replicar Comprobante&quot;.</li></ul><p><strong>Facturación masiva</strong> [M][T]</p><ul><li>Configurar Facturación Masiva [M].</li><li>Lote de facturación mensual: <code>FACTMES</code>, <code>FACTMES_COMP</code>, <code>FACTMES_CTAS</code>, <code>SFACTME</code>.</li></ul><p><strong>Conjuntos y grupos</strong> [M][T]</p><ul><li>Conjuntos de Facturación (<code>CONJUNTO</code>), Grupos de Facturación, Grupos de Factura (<code>GRUPOS_FACTURA</code>).</li></ul><p><strong>Diseño de la factura</strong> [M][T]</p><ul><li>Órdenes de impresión en Facturas.</li><li>Grupos de impresión de gráfico en facturas: <code>GRUPOS_GRAFICO</code>, <code>GRAFTAB</code> (gráfico de consumos en la factura).</li></ul><p><strong>Vencimientos</strong> [M][T]</p><ul><li>Tramas de vencimientos de Facturas: <code>TRAMASREC</code>, <code>CALENDARIO</code>.</li></ul><p><strong>Tipos de comprobante y talonarios</strong> [M][T]</p><ul><li>Tipos de Comprobantes: <code>TIP_COMP</code>, <code>TIPO_FAC</code>, <code>COMPROB</code>.</li><li>Puntos de venta: <code>PTOVENTA</code>.</li><li>Talonarios: <code>TALONFAC</code>, <code>TALONFAC_HST</code>, <code>TALONFAC_PAGO</code>.</li></ul><p><strong>Factura electrónica ARCA</strong> [P][M][T]</p><ul><li>Alerta al iniciar: &quot;Hay facturas electrónicas pendientes de autorizar&quot; y grilla &quot;Comprobantes Pendientes de Autorizar&quot; [P].</li><li>Tablas: <code>ELECTRONICA_FC</code>, <code>ELECTRONICA_IVA</code>, <code>ELECTRONICA_TRIB</code>, <code>ELECTRONICA_RELCOMP</code>, <code>EMPAFIP</code>.</li><li>Códigos de Autorización ARCA (CAEA, CESP) [M]: <code>CESPAFIP</code>.</li><li>Actividades ARCA: <code>ACTAFIP</code>.</li></ul><p><strong>Código de Validación Provincial (CVP)</strong> [M][T]</p><ul><li><code>CVPIIBB</code>.</li></ul><p><strong>Anulación</strong> [T]</p><ul><li><code>ANUFAC</code>, <code>ANUITEMSFAC</code>, <code>ANUITEMSFAC_EXTRAS</code>. La anulación queda en tablas espejo.</li></ul><p><strong>Causas de Bloqueo de Comprobantes</strong> [M]</p><ul><li>Tabla <code>CAUBLOQ</code> [T].</li></ul><p><strong>Facturación por cuenta de terceros</strong> [T]</p><ul><li><code>FACTURAS_TERCEROS</code>: tasas municipales, hospital y otras.</li></ul><p><strong>Relación entre comprobantes</strong> [T]</p><ul><li><code>RELACION_COMP</code>: por ejemplo, una nota de crédito que referencia a su factura.</li></ul><p><strong>Libro IVA Ventas</strong> [M]</p><ul><li>Tabla <code>IVAVTA</code> [T].</li></ul><p><strong>Informes de Ventas y Facturación, Movimiento de Conceptos</strong> [M].</p><p><strong>Energía comprada a EPEC</strong> [T]</p><ul><li><code>FACT_EPEC</code>. Indica la integración con la distribuidora provincial de Córdoba, que vende energía a la cooperativa [I].</li></ul><p><strong>Informe ENACOM</strong> [M]</p><ul><li>Configuración de Conceptos para informe ENACOM (servicios TIC).</li></ul><h3 id="mejoras-propuestas-7" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-7" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Facturación como proceso por lotes con estados:</strong><ol><li>Preparar.</li><li>Pre-facturar (borrador).</li><li>Revisar excepciones.</li><li>Aprobar.</li><li>Emitir y autorizar en ARCA.</li><li>Distribuir.</li></ol></li><li><strong>Autorización asíncrona en ARCA</strong> por cola (Queue Storage), con reintentos y tablero de pendientes. Elimina la alerta manual de &quot;pendientes de autorizar&quot;.</li><li><strong>PDF con QR de ARCA</strong> generado con QuestPDF.</li><li><strong>Distribución:</strong> envío por e-mail o WhatsApp y publicación en el portal.</li><li><strong>Anulación por nota de crédito asociada,</strong> nunca por borrado.</li><li><strong>Re-facturación de un servicio puntual</strong> sin re-procesar el lote.</li></ul><hr><h2 id="_10-modulo-9-—-cuenta-corriente-del-titular-a" tabindex="-1">10. Módulo 9 — Cuenta corriente del titular (A) <a class="header-anchor" href="#_10-modulo-9-—-cuenta-corriente-del-titular-a" aria-label="Permalink to &quot;10. Módulo 9 — Cuenta corriente del titular (A)&quot;">​</a></h2><h3 id="funciones-p-t-i" tabindex="-1">Funciones [P][T][I] <a class="header-anchor" href="#funciones-p-t-i" aria-label="Permalink to &quot;Funciones [P][T][I]&quot;">​</a></h3><p><strong>Deuda vencida</strong> [P]</p><ul><li>Se muestra en cada comprobante, en rojo.</li></ul><p><strong>Deuda por comprobante</strong> [T]</p><ul><li><code>DEUDAVTA</code>: deuda por venta o comprobante.</li><li><code>FACTURAS</code> se relaciona con <code>IT_RECCO</code> (ítems de recibos de cobro), <code>IT_PAGSO</code> (ítems de pagos del socio), <code>CAPITAL</code> y <code>COMPNOTI</code> (comprobantes notificados).</li></ul><p><strong>Anticipos y saldos a favor</strong> [T]</p><ul><li><code>ANTICIPOS</code>, <code>ANTIFACTU</code>.</li></ul><p><strong>Recargos por pago fuera de término</strong> [T]</p><ul><li><code>IT_PAGSO_INTERES</code>, <code>IT_PAGSO_INTERES_TRAMAS</code>.</li></ul><p><strong>Créditos no automáticos</strong> [T]</p><ul><li><code>CREDITOS_NOAUTOMATICOS</code>.</li></ul><h3 id="mejoras-propuestas-8" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-8" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Libro mayor del cliente</strong> como única fuente de verdad: cada débito (factura, nota de débito, interés) y cada crédito (pago, nota de crédito, anticipo) es un asiento.</li><li><strong>Saldo derivado</strong> de ese libro, nunca editable a mano.</li><li><strong>Imputación configurable:</strong> a la deuda más antigua primero, o a la que elija el titular.</li><li><strong>Pagos excedentes</strong> como saldo a favor.</li><li><strong>Estado de cuenta</strong> descargable por el socio.</li></ul><hr><h2 id="_11-modulo-10-—-cobranza-cajas-medios-de-pago-y-entes-recaudadores-a" tabindex="-1">11. Módulo 10 — Cobranza: cajas, medios de pago y entes recaudadores (A) <a class="header-anchor" href="#_11-modulo-10-—-cobranza-cajas-medios-de-pago-y-entes-recaudadores-a" aria-label="Permalink to &quot;11. Módulo 10 — Cobranza: cajas, medios de pago y entes recaudadores (A)&quot;">​</a></h2><h3 id="funciones-6" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-6" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Caja</strong> [M][T]</p><ul><li>Apertura de Caja, Cobranza Local y Cierre de Cajas.</li><li>Tablas: <code>CAJAS</code>, <code>CAJASJP</code>, <code>PLAN_CAJ</code>, <code>ANUPLAN_CAJ</code>, <code>CIERRE</code>.</li></ul><p><strong>Cobro</strong> [T]</p><ul><li><code>PAG_SOC</code> (pago del socio), <code>IT_PAGSO</code> (ítems del pago).</li><li>Anulación: <code>ANUPAG_SOC</code>, <code>ANUIT_PAGSO</code>.</li></ul><p><strong>Medios de pago</strong> [T]</p><ul><li><code>FORMAPA</code>, <code>FPITEMS</code>, <code>FPALIC_IVA</code>.</li><li>Tarjetas: <code>TARJETAS</code>, <code>TARJETAS_RECARGO</code>, <code>PAGOTAR</code>, <code>CUPONTAR</code>.</li><li>QR: <code>CAJAS_QR</code>.</li><li><code>CANALES_PAGOS</code>.</li></ul><p><strong>Descuentos en caja</strong> [P][T]</p><ul><li>Administración de Descuentos en Caja: <code>DESCUENTO_CAJA</code>.</li></ul><p><strong>Entes recaudadores</strong> [P][T]</p><ul><li>En la DEMO: DOCUMENTOS A COBRAR, RED LINK y SIRO.</li><li>Tablas: <code>ENTIDADES</code>, <code>ENTIDACOL*</code>, <code>ENTIDACON</code>, <code>ENTIDACOU</code>, <code>ENTIDACRIT</code>, <code>ENTIDADCIR</code>, <code>ENTIDAEST</code>, <code>ENTIDAGRUP</code>, <code>ENTIDAMEN</code>, <code>ENTIDA_ESTADOS</code>.</li><li>Empresas Tercerizadas [M].</li></ul><p><strong>Intercambio de archivos con los entes</strong> [P]</p><ul><li>Generar Archivo para Entidad Recaudadora.</li><li>Importar Archivo de Novedades.</li><li>Importar Archivo de Morosidad.</li><li>Tablas [T]: <code>RED_LINK</code>, <code>DEUDARED</code>, <code>DEUDARED_TIPO</code>, <code>SIRO_BASEDEUDA</code>, <code>RECHAZOS</code>.</li></ul><p><strong>Débito automático</strong> [P][T]</p><ul><li>Importar y exportar archivos de débitos automáticos. Exclusiones: <code>DEBITO_EXCLUSION</code>.</li><li>Carpeta <code>Debitos</code> entre los binarios.</li></ul><p><strong>Pagos online</strong> [T]</p><ul><li>Pagos360: <code>PAGOS360</code>, <code>PAGOS360_ITEMS</code>, <code>PAGOS360_PAGOS</code>, <code>PAGOS360_EXTRAS</code>.</li></ul><p><strong>Retenciones sufridas en cobros</strong> [M][T]</p><ul><li>Retenciones Recibidas: <code>RETENCIO</code>, <code>IT_RETM</code>.</li></ul><p><strong>Opciones e Informes de Cobranza</strong> [M][T]</p><ul><li><code>ESQUEMAS_INFORMES_COBRANZAS</code>, <code>COBRANZA_LOG</code>.</li></ul><p><strong>Recibos</strong> [T]</p><ul><li><code>REC_CON</code>, <code>IT_RECCO</code>.</li></ul><h3 id="mejoras-propuestas-9" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-9" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Conectores por ente</strong> (RED LINK, SIRO, Pagos360, bancos): <ul><li>Generación automática del archivo de deuda tras cada facturación.</li><li>Ingesta automática de la rendición.</li><li>Conciliación con diferencias explícitas.</li></ul></li><li><strong>Pago online en el portal:</strong> botón de pago, QR interoperable y link de pago por WhatsApp.</li><li><strong>Caja web:</strong> cobro por código de barras de la factura, arqueo y cierre con diferencias.</li><li><strong>Bandeja de pagos no identificados.</strong></li></ul><hr><h2 id="_12-modulo-11-—-gestion-de-mora-y-corte-a" tabindex="-1">12. Módulo 11 — Gestión de mora y corte (A) <a class="header-anchor" href="#_12-modulo-11-—-gestion-de-mora-y-corte-a" aria-label="Permalink to &quot;12. Módulo 11 — Gestión de mora y corte (A)&quot;">​</a></h2><h3 id="funciones-7" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-7" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Instancias de mora</strong> [P]</p><ul><li>1 CANDIDATOS, 2 PRIMER INSTANCIA, 3 SEGUNDA INSTANCIA.</li><li>Tablas: <code>INSTANCI</code> [T] y Instancias de Mora [M].</li></ul><p><strong>Generar Notificaciones (1ª instancia)</strong> [M]</p><ul><li>Tablas: <code>NOTIFICA</code>, <code>COMPNOTI</code>, <code>RESPONSA_NOTIFICA</code>, <code>NOTI_COOP</code> [T].</li></ul><p><strong>Tratamiento de Notificaciones Generadas y Tratamiento de Morosos</strong> [M]</p><ul><li>Tabla: <code>MOROSO_TEMPORAL</code> [T].</li></ul><p><strong>Excepciones de Mora</strong> [M]</p><ul><li>Tabla: <code>EXC_MORA</code> [T].</li></ul><p><strong>Causas de Baja</strong> [M]</p><ul><li>Tabla: <code>CAUSAS</code> [T].</li></ul><p><strong>Tasas e índices de recargo</strong> [P][T]</p><ul><li>Administración de Tasas de Mora.</li><li>Tablas de Índices para Recargo por Mora: <code>TABMORA</code>, <code>INDICESMORA</code>.</li><li>Tasa por servicio y categoría: <code>MORATAS</code>, <code>MORATAS_CATSER</code>.</li></ul><p><strong>Operaciones Especiales de mora</strong> [M].</p><p><strong>Informes de Gestión de Mora</strong> [M].</p><h3 id="flujo-inferido-i" tabindex="-1">Flujo inferido [I] <a class="header-anchor" href="#flujo-inferido-i" aria-label="Permalink to &quot;Flujo inferido [I]&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Factura vencida</span></span>
<span class="line"><span>  → Candidato</span></span>
<span class="line"><span>  → Notificación de 1ª instancia (aviso)</span></span>
<span class="line"><span>  → 2ª instancia (intimación)</span></span>
<span class="line"><span>  → Orden de corte (técnica)</span></span>
<span class="line"><span>  → Corte</span></span>
<span class="line"><span>  → Reconexión al pagar o financiar</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Las excepciones de mora excluyen cuentas del proceso, por ejemplo entidades públicas o electrodependientes.</p><h3 id="mejoras-propuestas-10" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-10" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Política de mora configurable</strong> por servicio y categoría: días, montos mínimos, instancias, canal de aviso.</li><li><strong>Exclusiones normativas</strong> (electrodependientes, entre otras) y aprobación del corte.</li><li><strong>Integración con Técnica:</strong> el corte y la reconexión generan órdenes de trabajo automáticamente.</li><li><strong>Avisos con constancia de entrega:</strong> e-mail, SMS, WhatsApp y carta.</li></ul><hr><h2 id="_13-modulo-12-—-financiacion-y-planes-de-pago-b" tabindex="-1">13. Módulo 12 — Financiación y planes de pago (B) <a class="header-anchor" href="#_13-modulo-12-—-financiacion-y-planes-de-pago-b" aria-label="Permalink to &quot;13. Módulo 12 — Financiación y planes de pago (B)&quot;">​</a></h2><h3 id="funciones-m-t" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Emitir Plan de Financiación e Informes de Financiaciones</strong> [M]</p><ul><li>Tablas: <code>PPAGOS</code> (plan de pagos), <code>PPITEMS</code>, <code>PPAGOS_FIRMANTES</code>, <code>PPAGOS_FIRMAS</code> [T]. El plan lleva firma del titular y de los garantes.</li></ul><p><strong>Planes de cuotas</strong> [M][T]</p><ul><li>Planes de Cuotas: <code>PLAN_CUO</code>.</li><li>Entidades financieras: <code>ENTFIN</code>, <code>TIP_FIN</code>.</li></ul><p><strong>Financiación de ventas</strong> [M][I]</p><ul><li>Cuotas cargadas en la factura del servicio.</li></ul><h3 id="mejoras-propuestas-11" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-11" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Simulador de plan:</strong> anticipo, cuotas, tasa y CFT.</li><li><strong>Firma digital</strong> del convenio.</li><li><strong>Caída automática del plan</strong> por cuotas impagas y re-exigibilidad de la deuda.</li></ul><hr><h2 id="_14-modulo-13-—-ventas-presupuestos-y-punto-de-venta-b" tabindex="-1">14. Módulo 13 — Ventas, presupuestos y punto de venta (B) <a class="header-anchor" href="#_14-modulo-13-—-ventas-presupuestos-y-punto-de-venta-b" aria-label="Permalink to &quot;14. Módulo 13 — Ventas, presupuestos y punto de venta (B)&quot;">​</a></h2><h3 id="funciones-m-t-1" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-1" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Presupuestos</strong> [M]</p><ul><li>Tablas: <code>PRESUPU</code>, <code>PRESUIT</code>, <code>PRESUIT_CONJUNTOS</code>, <code>PRESUPU_CONDICION</code>, <code>PRESUPU_NOTAS</code>, <code>PRESUPU_COMPROBANTES</code>.</li><li>Condiciones de Venta para Presupuestos [M].</li></ul><p><strong>Venta de Productos</strong> [M]</p><ul><li>Comprobantes de venta y su rendición: <code>COMP_VEN</code>, <code>IT_COMPV</code>, <code>OB_COMPV</code>, <code>COMP_VEN_RENDICION*</code>.</li></ul><p><strong>Vendedores</strong> [M][T]</p><ul><li><code>VENDEDOR</code>.</li></ul><p><strong>POS</strong> [T]</p><ul><li><code>COMPPOS</code>, <code>DESCPOS</code>.</li><li>Telefonía POS: <code>TEL_POS_REG_*</code>.</li></ul><p><strong>Conceptos por cobrar en operaciones con titulares</strong> [M]</p><ul><li>Por ejemplo derechos de conexión o reconexión, que se facturan con el servicio.</li></ul><h3 id="mejoras-propuestas-12" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-12" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Presupuesto, aceptación online, orden de trabajo y factura, en un flujo continuo.</li></ul><hr><h2 id="_15-modulo-14-—-tecnica-factibilidades-ordenes-de-trabajo-y-reclamos-b" tabindex="-1">15. Módulo 14 — Técnica: factibilidades, órdenes de trabajo y reclamos (B) <a class="header-anchor" href="#_15-modulo-14-—-tecnica-factibilidades-ordenes-de-trabajo-y-reclamos-b" aria-label="Permalink to &quot;15. Módulo 14 — Técnica: factibilidades, órdenes de trabajo y reclamos (B)&quot;">​</a></h2><h3 id="funciones-8" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-8" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Administración de Factibilidades</strong> [M]</p><ul><li>Tablas: <code>FACTIBIL</code>, <code>FACTIBIL_NOTA</code> [T].</li><li>El servicio guarda el &quot;Id Factibilidad&quot; de la factibilidad que lo originó [P].</li></ul><p><strong>Administración de Órdenes de trabajo</strong> [M]</p><ul><li>Tablas: <code>TECNICA</code>, <code>TECNICA_EXTRAS</code>, <code>TECNICA_NOTA</code>, <code>TECNICA_NECESIDAD</code>, <code>ITEMSORD</code> (materiales), <code>RESOL_OT</code> (resolución), <code>OT_REPORTE</code> [T].</li></ul><p><strong>Carga Rápida de Reclamos</strong> [M]</p><ul><li>Tablas: <code>RECLAMOS</code>, <code>RECLAMOS_HIST</code>, <code>RECLAMOS_NOTAS</code>, <code>FALLAS</code> [T].</li></ul><p><strong>Tareas y cuadrillas</strong> [T]</p><ul><li><code>TAREAS</code>, <code>TAREASOM</code>, <code>GRPTAREA</code>, <code>CUADRI</code> (cuadrillas), <code>OPERADOR</code>, <code>TPTRAB</code>.</li></ul><p><strong>Ejecución en campo</strong> [T]</p><ul><li>App móvil: <code>TECNICA_MOVIL</code>.</li><li>Materiales retirados: <code>RETI_MAT</code>.</li></ul><p><strong>Obras</strong> [T]</p><ul><li><code>OBRAS</code>, <code>GRPOBRA</code>.</li></ul><p><strong>Clasificación técnica y expedientes</strong> [T]</p><ul><li><code>TECNGREXP</code>, <code>TECNOTEXP</code>, <code>TECNSEEXP</code>.</li></ul><p><strong>Informes técnicos</strong> [M].</p><h3 id="mejoras-propuestas-13" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-13" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Tablero de órdenes:</strong> kanban y mapa, con asignación a cuadrillas.</li><li><strong>App de campo:</strong> fotos, firma del cliente, materiales usados que descuentan stock, y cierre con lectura de medidor.</li><li><strong>Reclamos:</strong> SLA por tipo y aviso al socio de cada cambio de estado.</li><li><strong>Integración con mora:</strong> corte y reconexión.</li><li><strong>Factibilidad como paso previo obligatorio</strong> del alta de servicio.</li></ul><hr><h2 id="_16-modulo-15-—-redes-e-infraestructura-gis-c" tabindex="-1">16. Módulo 15 — Redes e infraestructura (GIS) (C) <a class="header-anchor" href="#_16-modulo-15-—-redes-e-infraestructura-gis-c" aria-label="Permalink to &quot;16. Módulo 15 — Redes e infraestructura (GIS) (C)&quot;">​</a></h2><h3 id="funciones-t-p" tabindex="-1">Funciones [T][P] <a class="header-anchor" href="#funciones-t-p" aria-label="Permalink to &quot;Funciones [T][P]&quot;">​</a></h3><p><strong>Red eléctrica</strong> [T]</p><ul><li>Componentes, atributos, capas, relaciones y red instalada: <code>REDES</code>, <code>REDES_ATRIBUTOS</code>, <code>REDES_ATRIBUTOS_COMPONENTES</code>, <code>REDES_CAPAS</code>, <code>REDES_COMPONENTES</code>, <code>REDES_RED_INSTALADA</code>, <code>REDES_RELACIONES_COMPONENTES</code>.</li></ul><p><strong>Vínculo servicio–red</strong> [T]</p><ul><li><code>REDES_SERVICIOS</code>, <code>SERSOC_REDES</code>. Indica, por ejemplo, de qué transformador cuelga cada suministro.</li><li>Niveles: <code>NIV_CAPA</code>, <code>NIV_REDES</code>, <code>NIV_SERV</code>.</li></ul><p><strong>Mapa</strong> [P][T]</p><ul><li><code>MAPA</code>, <code>UBICACIONES</code> y las coordenadas de cada servicio.</li><li>Campo &quot;GIS&quot; en la ficha.</li></ul><p><strong>Equipos de red</strong> [T]</p><ul><li><code>EQUIPOS</code>, <code>CENTRALT</code>.</li></ul><h3 id="mejoras-propuestas-14" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-14" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Mapa web</strong> de suministros, red, reclamos y órdenes.</li><li><strong>Análisis de impacto:</strong> qué socios se afectan ante el corte de un transformador, con aviso masivo.</li></ul><hr><h2 id="_17-modulo-16-—-compras-y-proveedores-b" tabindex="-1">17. Módulo 16 — Compras y proveedores (B) <a class="header-anchor" href="#_17-modulo-16-—-compras-y-proveedores-b" aria-label="Permalink to &quot;17. Módulo 16 — Compras y proveedores (B)&quot;">​</a></h2><h3 id="circuito-m-t" tabindex="-1">Circuito [M][T] <a class="header-anchor" href="#circuito-m-t" aria-label="Permalink to &quot;Circuito [M][T]&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Solicitud de Aprovisionamiento (SAPROV / IT_APROV)</span></span>
<span class="line"><span>  → Solicitud de Cotización (SCOTIZ / IT_SCOTIZ)</span></span>
<span class="line"><span>  → Orden de Compra (OCOMPRA / CMPORDE)</span></span>
<span class="line"><span>  → Nota de Pedido (NPEDIDO / IT_NPED)</span></span>
<span class="line"><span>  → Remito de Proveedor / Recepción (RECEPCIONES / ESTADOS_RECEP)</span></span>
<span class="line"><span>  → Comprobante de Proveedor (COMP_COM / IT_COMPC / MOV_PRO)</span></span>
<span class="line"><span>  → Pago a Proveedores, con Retenciones (CON_COM_RET / RET_COM)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="funciones-9" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-9" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Proveedores</strong> [T]</p><ul><li><code>PROVEED</code>, <code>PROVEED_CBU</code>, <code>PROVEED_RET</code>, <code>PROVEED_TIPPROD</code>, <code>PROVEED_AUT</code>, <code>PROVEED_VALORACIONES</code> (evaluación de proveedores).</li><li>Rubros: <code>RUBPROV</code>, <code>RUBXPRO</code>.</li><li>Circuito y observaciones: <code>CIRCUPRO</code>, <code>OBS_PRO</code>.</li></ul><p><strong>Retenciones a Proveedores</strong> [M][T]</p><ul><li>Ganancias, IVA e IIBB: <code>RETE_TIPO</code>, <code>RETE_TIPO_BASE</code>, <code>RETS_TIPO</code>, <code>CAT_RETG</code>.</li><li>Ligado a SICORE / SIRE [I].</li></ul><p><strong>Libro de IVA Compras</strong> [M][T]</p><ul><li><code>IVACOM</code>, <code>IVACOM_COMBUSTIBLES</code>, <code>IVACOM_WEB</code>.</li></ul><p><strong>Otros</strong> [M][T]</p><ul><li>Informes de Compras, Correspondencia.</li><li><code>COMPRAS_RELACION</code>, <code>OPE_COM</code>, <code>CON_COM</code>.</li><li><code>RPSPROV</code>, <code>RPSXPROV</code>.</li></ul><h3 id="mejoras-propuestas-15" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-15" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Aprobaciones por monto.</strong></li><li><strong>Control de 3 vías:</strong> orden de compra, recepción y factura.</li><li><strong>Importación de comprobantes recibidos</strong> desde ARCA (&quot;Mis Comprobantes&quot;).</li><li><strong>Pago por transferencia</strong> con archivo para Interbanking.</li></ul><hr><h2 id="_18-modulo-17-—-stock-bienes-de-uso-rma-y-fabricacion-b" tabindex="-1">18. Módulo 17 — Stock, bienes de uso, RMA y fabricación (B) <a class="header-anchor" href="#_18-modulo-17-—-stock-bienes-de-uso-rma-y-fabricacion-b" aria-label="Permalink to &quot;18. Módulo 17 — Stock, bienes de uso, RMA y fabricación (B)&quot;">​</a></h2><h3 id="funciones-m-t-2" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-2" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Movimientos de Stock</strong> [M]</p><ul><li>Depósitos: <code>DEPOSITO</code>, <code>DEPAPROD</code>.</li><li>Transferencias: <code>TRANSFER</code>.</li><li>Tipos de producto: <code>TIP_PROD</code>, <code>CLASIFICACION_ITEMS</code>.</li></ul><p><strong>Trazabilidad</strong> [M]</p><ul><li>Números de serie y lotes: <code>TIPOLOTE</code> [T].</li></ul><p><strong>Operaciones Especiales</strong> [M].</p><p><strong>Bienes de Uso</strong> [M][T]</p><ul><li><code>BIENES_USO</code>, <code>BIENES_USO_AMORT</code> (amortizaciones), <code>BIENES_USO_DISM</code> (bajas), <code>BIENES_USO_HST</code>, <code>BIENES_USO_CTSEC</code> (imputación contable).</li></ul><p><strong>Fabricación</strong> [M][T]</p><ul><li>Productos fabricados y sus divisiones: <code>PRODFAB</code>, <code>PRODFAB_DIVISIONES</code>, <code>HIS_PRODFAB</code>.</li><li>Órdenes de fabricación: <code>ORDEFAB</code>, <code>ORDEFAB_EXT</code>, <code>ORDAFAB</code>, <code>ORCOFAB</code>, <code>ORPRFAB</code>.</li><li>Etapas: <code>ETAFAB</code>.</li><li>Partes: <code>OF_PARTE_COMPONENTE</code>, <code>OF_PARTE_ITEM</code>, <code>OF_PARTE_PRODUCCION</code>.</li></ul><p><strong>RMA (devoluciones y reparaciones)</strong> [M][T]</p><ul><li><code>RMA_PRODUCTOS</code>, <code>RMA_HISTORIAL</code>.</li></ul><p><strong>Informes de Stock</strong> [M].</p><p><strong>Unidades de gasto</strong> [T]</p><ul><li><code>UNIDADES_GASTOS</code>.</li></ul><h3 id="mejoras-propuestas-16" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-16" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Consumo de materiales desde la orden de trabajo</strong> en la app de campo.</li><li><strong>Stock mínimo</strong> con sugerencia de compra.</li><li><strong>Medidores y equipos serializados</strong> con su ubicación: depósito, cuadrilla o domicilio del socio.</li></ul><hr><h2 id="_19-modulo-18-—-tesoreria-y-bancos-b" tabindex="-1">19. Módulo 18 — Tesorería y bancos (B) <a class="header-anchor" href="#_19-modulo-18-—-tesoreria-y-bancos-b" aria-label="Permalink to &quot;19. Módulo 18 — Tesorería y bancos (B)&quot;">​</a></h2><h3 id="funciones-m-t-3" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-3" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Bancos</strong> [M][T]</p><ul><li>Movimientos Bancarios y Cuentas Bancarias Propias.</li><li>Tablas: <code>BANCOS</code>, <code>BANKOS</code>, <code>Banco</code>, <code>BANCLA</code>, <code>CAT_BANC</code>, <code>TIPOBAN</code>, <code>CATB_MOVS</code>.</li></ul><p><strong>Conciliación bancaria</strong> [T]</p><ul><li><code>RESBAN</code>, <code>RESBAN_MOVINT</code>.</li></ul><p><strong>Interbanking</strong> [T]</p><ul><li><code>INTERBANKING</code>, <code>MOV_INTERBANKING</code>, <code>SU_AUDIT_TRA_INTERBANKING</code>.</li></ul><p><strong>Movimientos en Tesorería</strong> [M][T]</p><ul><li><code>TESORE</code>, <code>MOV_TRH</code>, <code>TRAN_OP</code>, <code>EFEC_OP</code>, <code>CONTES</code>.</li></ul><p><strong>Valores</strong> [M][T]</p><ul><li>Valores de Terceros, Cheques Propios, Cupones de Tarjetas.</li><li>Tablas: <code>VALORES</code>, <code>VAL_ESTA</code>, <code>VAL_MVTO</code>, <code>CHEQUERAS</code>, <code>TIP_VAL</code>, <code>CUPONTAR</code>.</li></ul><p><strong>Monedas</strong> [T]</p><ul><li><code>TIP_MON</code>, <code>COT_DOL</code>.</li></ul><p><strong>Cajas para Pagos a Proveedores</strong> [M][T]</p><ul><li><code>CAJAPAGO</code>.</li></ul><p><strong>Cierre de Cajas e Informes de Tesorería</strong> [M].</p><h3 id="mejoras-propuestas-17" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-17" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Importación de extractos</strong> con conciliación asistida.</li><li><strong>eCheq.</strong></li><li><strong>Flujo de fondos proyectado</strong> a partir de vencimientos a cobrar y a pagar.</li></ul><hr><h2 id="_20-modulo-19-—-contabilidad-b" tabindex="-1">20. Módulo 19 — Contabilidad (B) <a class="header-anchor" href="#_20-modulo-19-—-contabilidad-b" aria-label="Permalink to &quot;20. Módulo 19 — Contabilidad (B)&quot;">​</a></h2><h3 id="funciones-m-t-4" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-4" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Asientos</strong> [M][T]</p><ul><li><code>CTASIEN</code>, <code>CTITASIE</code>, <code>CTITASIE_SECCIONES</code>.</li></ul><p><strong>Consultar Mayor y Balance General / Sumas y Saldos</strong> [M].</p><p><strong>Plan de cuentas</strong> [T]</p><ul><li><code>CTPLAN</code>, <code>CTPLAN_SUBRUBROS</code>, <code>CTSRUBROS</code>.</li></ul><p><strong>Ejercicios</strong> [T]</p><ul><li><code>CTEJER</code>.</li></ul><p><strong>Centros de costo o secciones</strong> [T]</p><ul><li><code>CTSECCION</code>, <code>CTSECCION_ASIGNA</code>, <code>CTSECCION_GRUPOS</code>, <code>CTSECCION_GP_ASIGNA</code>, <code>CTSECC_X_CTA</code>.</li></ul><p><strong>Asientos Automáticos</strong> [M][T]</p><ul><li>Cada módulo tiene su imputación contable: <ul><li>Asignación de cuentas: <code>CTCUENTA_ASIGNA</code>.</li><li>Bienes de uso: <code>BIENES_USO_CTSEC</code>.</li><li>Medios de pago: <code>FPITEMS_CTSEC</code>.</li><li>Obras: <code>GRPOBRA_CTSEC</code>.</li><li>Incidentes: <code>CAT_INCI_CTSEC</code>.</li></ul></li></ul><p><strong>Categorías INAES</strong> [T]</p><ul><li><code>CAT_INAES</code>, para la información al organismo de control de cooperativas.</li></ul><p><strong>Herramientas, Informes Contables e Informes de Gestión</strong> [M].</p><p><strong>Sistema contable externo</strong> [T]</p><ul><li><code>SISCONT</code>: probable integración o exportación a otro sistema contable.</li></ul><h3 id="mejoras-propuestas-18" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-18" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Contabilización en tiempo real</strong> desde cada evento (factura, cobro, pago, liquidación), con reglas configurables.</li><li><strong>Cierre de período</strong> con bloqueo.</li><li><strong>Estados contables</strong> en formato INAES.</li></ul><hr><h2 id="_21-modulo-20-—-sueldos-y-personal-c" tabindex="-1">21. Módulo 20 — Sueldos y personal (C) <a class="header-anchor" href="#_21-modulo-20-—-sueldos-y-personal-c" aria-label="Permalink to &quot;21. Módulo 20 — Sueldos y personal (C)&quot;">​</a></h2><h3 id="funciones-m-t-5" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-5" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Empleados</strong> [M][T]</p><ul><li><code>SU_EMPLEADOS</code>, <code>SU_EMPLEADOS_DOCUMENTOS</code>, <code>SU_EMPLEADOS_SEC</code>.</li><li>Familiares: <code>SU_EMP_FAMILIARES</code>.</li><li>CBU: <code>SU_EMP_CBU</code>.</li><li>Novedades: <code>SU_EMP_NOVEDADES</code>.</li><li>Turnos: <code>SU_EMP_TURNOS</code>, <code>SU_TURNOS</code>.</li><li>Historial de categoría: <code>SU_EMP_HISCAT_EMP</code>.</li><li>Situación de revista: <code>SU_SITUACION_REVISTA</code>.</li><li>Licencias: <code>SU_LICENCIAS</code>.</li></ul><p><strong>Empresas empleadoras</strong> [M][T]</p><ul><li><code>SU_EMPRESAS</code>, <code>SU_TIPOEMPLEADOR</code>.</li></ul><p><strong>Recibos de sueldo</strong> [M][T]</p><ul><li><code>SU_SUELDOS</code>, <code>SU_SUELDOSIT</code>, <code>SU_TIPO_RECIBOS</code>.</li></ul><p><strong>Liquidación Masiva y Simulador</strong> [M].</p><p><strong>Impuesto a las Ganancias</strong> [M][T]</p><ul><li><code>SU_DEDUCCIONES*</code>, <code>SU_SUELDOS_DETGAN</code>.</li></ul><p><strong>Configuración</strong> [M][T]</p><ul><li>Variables, Conceptos y Aplicar Aumentos: <code>SU_VARIABLES</code>, <code>SU_CONCEPTOS</code>, <code>SU_CONCEPTO_TIPO</code>.</li><li>Categorías, cargos, sindicatos y salario mínimo: <code>SU_CATE</code>, <code>SU_CARGO</code>, <code>SU_SINDICATO</code>, <code>SU_SALARIO_MINIMO</code>.</li></ul><p><strong>Seguridad social</strong> [T]</p><ul><li>SICOSS: <code>SU_BENEFICIOS_SICOSS</code>.</li><li>ART / siniestros: <code>SU_SINIESTRADO</code>.</li></ul><p><strong>Asientos de sueldos</strong> [T]</p><ul><li><code>SU_ASIENTOS</code>.</li></ul><p><strong>Libro de sueldos digital</strong> [M]</p><ul><li>Deshabilitado en la DEMO.</li></ul><h3 id="mejoras-propuestas-19" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-19" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Evaluar si conviene integrar un liquidador de sueldos externo en lugar de construirlo.</li><li>Portal del empleado con recibos y firma digital.</li></ul><hr><h2 id="_22-modulo-21-—-atencion-mesa-de-entradas-turnero-y-comunicaciones-b" tabindex="-1">22. Módulo 21 — Atención: mesa de entradas, turnero y comunicaciones (B) <a class="header-anchor" href="#_22-modulo-21-—-atencion-mesa-de-entradas-turnero-y-comunicaciones-b" aria-label="Permalink to &quot;22. Módulo 21 — Atención: mesa de entradas, turnero y comunicaciones (B)&quot;">​</a></h2><h3 id="funciones-10" tabindex="-1">Funciones <a class="header-anchor" href="#funciones-10" aria-label="Permalink to &quot;Funciones&quot;">​</a></h3><p><strong>Mesa de Entradas</strong> [M][T]</p><ul><li>Administración, Consulta de Incidentes e Informes.</li><li>Sistema de tickets: <ul><li>Tipos, subtipos y estados: <code>TICKETS</code>, <code>TICKETS_TIPOS</code>, <code>TICKETS_SUBTIPOS</code>, <code>TICKETS_ESTADOS</code>, <code>TICKETS_TIPOSESTADOS</code>.</li><li>Responsables y asignaciones: <code>TICKETS_RESPONSABLES</code>, <code>TICKETS_ASIGNACIONES</code>.</li><li>Contactos y notas: <code>TICKETS_CONTACTOS</code>, <code>TICKETS_NOTAS</code>.</li><li>Medios de atención y módulos: <code>TICKETS_MEDIOSATENCION</code>, <code>TICKETS_MODULOS</code>.</li><li>Proyectos y horas bonificadas: <code>TICKETS_PROYECTO</code>, <code>TICKETS_HSBONIF</code>.</li></ul></li><li>Incidentes: <code>CAT_INCI</code>, <code>CLAS_INC</code>, <code>PARTIINC</code>.</li></ul><p><strong>Turnero</strong> [M][T]</p><ul><li>Administración de Box, Turnero, Selección de Turnos y Estadísticas.</li><li>Tablas: <code>TURNOS</code>, <code>TURNOS_HISTORIAL</code>, <code>TUR_AREAS</code>, <code>TUR_AREAS_USERS</code>, <code>TUR_BOX</code>, <code>TUR_BOX_HISTORIAL</code>, <code>TUR_TIPO_BOX</code>.</li></ul><p><strong>Telefonía y llamadas</strong> [T]</p><ul><li><code>LLAMADAS</code>, <code>TIPOLLAM</code>, <code>IVR</code>, <code>RNQCALL</code>, <code>ENTRANTE</code>.</li></ul><p><strong>SMS</strong> [M]</p><ul><li>Administración de SMS.</li></ul><p><strong>Correo y mensajería</strong> [T]</p><ul><li><code>SENDMAIL</code>, <code>PROMAIL</code>, <code>CORREOSINT</code>, <code>CORREOS_INTERNOS</code>, <code>MENSAJES</code>, <code>ENVIOS</code>, <code>MailTemplates</code>.</li></ul><p><strong>WhatsApp</strong> [P][T]</p><ul><li>Botón en la ficha del titular [P].</li><li>Plantillas: <code>PLANTILLA_WSP</code>, <code>VARIABLES_PLANTILLA_WSP</code> [T].</li></ul><p><strong>Plantillas de documentos</strong> [T]</p><ul><li><code>PLANTILLA</code>, <code>VARIABLEPLANT</code>, <code>CIRCULAR</code>.</li></ul><p><strong>Encuestas</strong> [T]</p><ul><li><code>ENCUESTAS</code>, <code>RESPUESTAS</code>, <code>RESULTA</code>, <code>RESULTADOS</code>.</li></ul><p><strong>Noticias y centro de notificaciones</strong> [P][T]</p><ul><li>Panel &quot;Próximamente / Noticias Procoop&quot; y &quot;Centro de notificaciones&quot; en la pantalla principal [P].</li><li>Tablas: <code>RSSFEED</code>, <code>WEB_NOVEDADES</code>.</li></ul><h3 id="mejoras-propuestas-20" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-20" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>CRM unificado:</strong> todas las interacciones del socio (llamada, WhatsApp, mail, ventanilla, portal) en un solo historial ligado a la cuenta.</li><li><strong>WhatsApp Business API</strong> con plantillas aprobadas y bot de autogestión: saldo, segunda vía de factura, reclamo.</li><li><strong>Turnero web</strong> con turno online.</li></ul><hr><h2 id="_23-modulo-22-—-actividades-y-tareas-internas-c" tabindex="-1">23. Módulo 22 — Actividades y tareas internas (C) <a class="header-anchor" href="#_23-modulo-22-—-actividades-y-tareas-internas-c" aria-label="Permalink to &quot;23. Módulo 22 — Actividades y tareas internas (C)&quot;">​</a></h2><h3 id="funciones-m-t-6" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-6" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><ul><li>Seguimiento e Informe.</li><li>Tablas: <code>ACTIV</code>, <code>ACTIV_SEG</code>, <code>ACT_AREAS</code>, <code>ACT_FREC</code>, <code>ACT_RBR</code>, <code>ACT_TIPOS</code>, <code>ACTIPREV</code> (actividades preventivas), <code>HISWORK</code>, <code>IMP_WORK</code>.</li></ul><p><strong>Tablero de Control</strong> [M][T]</p><ul><li><code>TABLERO</code>.</li></ul><hr><h2 id="_24-modulo-23-—-traslados-y-flota-c" tabindex="-1">24. Módulo 23 — Traslados y flota (C) <a class="header-anchor" href="#_24-modulo-23-—-traslados-y-flota-c" aria-label="Permalink to &quot;24. Módulo 23 — Traslados y flota (C)&quot;">​</a></h2><h3 id="funciones-m-t-7" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-7" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><ul><li>Administración de Viajes, Informes, Rendiciones de Viajes [M].</li><li>Choferes y vehículos: <code>CHOFERES</code>, <code>MAQUINAS</code>.</li><li>Combustibles: <code>COMBUSTIBLES</code>, <code>IVACOM_COMBUSTIBLES</code>.</li><li>Seguimiento GPS: <code>AVL_REG</code> y la DLL <code>AVL.dll</code>.</li><li>Ambulancias, ligado a los servicios sociales: <code>AMBULANC</code>, <code>AMBUCARACTE</code>, <code>AMBUMED</code>.</li></ul><hr><h2 id="_25-modulo-24-—-gestion-institucional-c" tabindex="-1">25. Módulo 24 — Gestión institucional (C) <a class="header-anchor" href="#_25-modulo-24-—-gestion-institucional-c" aria-label="Permalink to &quot;25. Módulo 24 — Gestión institucional (C)&quot;">​</a></h2><h3 id="funciones-t-i" tabindex="-1">Funciones [T][I] <a class="header-anchor" href="#funciones-t-i" aria-label="Permalink to &quot;Funciones [T][I]&quot;">​</a></h3><ul><li><strong>Asociados:</strong> registro, número de asociado y antigüedad: <code>SOCIOS</code>, <code>SU_ANTIGUE</code>.</li><li><strong>Capital social:</strong> suscripción e integración, cobrada en la factura: <code>CAPITAL</code>, <code>CAPITAL_RES</code>, <code>RUBCAPI</code>. <code>FACTURAS</code> y <code>SERVICIO</code> se relacionan con <code>CAPITAL</code>.</li><li><strong>Consejo de administración y actas:</strong> <code>CONSEJO</code>, <code>ACTAS</code>.</li><li><strong>Reuniones y asambleas:</strong> <code>REUNIONES</code>, <code>REUNIONES_ASIST</code>, <code>REUNIONES_PERMISOS</code>, <code>REUNIONES_TEMAS</code>.</li></ul><h3 id="mejoras-propuestas-21" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-21" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li>Padrón de asociados para asambleas.</li><li>Convocatoria y registro de asistencia.</li></ul><hr><h2 id="_26-modulo-25-—-servicios-sociales-y-otros-servicios-c" tabindex="-1">26. Módulo 25 — Servicios sociales y otros servicios (C) <a class="header-anchor" href="#_26-modulo-25-—-servicios-sociales-y-otros-servicios-c" aria-label="Permalink to &quot;26. Módulo 25 — Servicios sociales y otros servicios (C)&quot;">​</a></h2><h3 id="funciones-m-t-8" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-8" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><p><strong>Planes de Vivienda</strong> [M][T]</p><ul><li>Materiales para Viviendas, Construcción de Vivienda e Informes.</li><li>Tablas: <ul><li><code>PLANESVIV</code>, <code>VIVIENDAS</code>, <code>PRECIOSVIV</code>.</li><li>Etapas, actividades y progreso: <code>VIV_ETAPA</code>, <code>VIV_ACTIVIDAD</code>, <code>VIV_PROGRESO</code>.</li><li>Materiales: <code>VIV_MAT</code>, <code>VIV_MATACT</code>, <code>VIV_PROGMAT</code>.</li><li>Retiros de materiales: <code>VIV_RETM</code>, <code>VIV_RET_IT</code>.</li></ul></li></ul><p><strong>Servicios de salud y emergencias</strong> [T]</p><ul><li><code>AMBULANC</code>, <code>MEDICOS</code>, <code>INTERNAC</code>.</li></ul><p><strong>Telefonía</strong> [M][T]</p><ul><li>Centrales y DSLAM: <code>TEL_CENTRAL</code>, <code>TEL_DSLAM</code>.</li><li>Repartidores y regletas: <code>TEL_REPARTIDOR</code>, <code>TEL_REGLETAS_*</code>.</li><li>Números, prefijos y tarifas: <code>TEL_NUMEROS</code>, <code>TEL_PREFIJO</code>, <code>TARTEL</code>.</li><li>Llamadas facturables: <code>LLA_CEL</code>.</li></ul><p><strong>Internet</strong> [T]</p><ul><li><code>INTERNET</code>, <code>MIKROTIK</code> (integración con routers MikroTik para habilitar o cortar), <code>MODEMS</code>, <code>SERVINT</code>.</li></ul><hr><h2 id="_27-modulo-26-—-autogestion-del-socio-portal-y-app-b" tabindex="-1">27. Módulo 26 — Autogestión del socio: portal y app (B) <a class="header-anchor" href="#_27-modulo-26-—-autogestion-del-socio-portal-y-app-b" aria-label="Permalink to &quot;27. Módulo 26 — Autogestión del socio: portal y app (B)&quot;">​</a></h2><h3 id="funciones-m-t-p" tabindex="-1">Funciones [M][T][P] <a class="header-anchor" href="#funciones-m-t-p" aria-label="Permalink to &quot;Funciones [M][T][P]&quot;">​</a></h3><p><strong>Procoop WEB / CoopOnline</strong> [M][T]</p><ul><li>Menús: Requisitos y Trámites, Archivos en la Web, Operaciones.</li><li>El namespace <code>CapaDatos.PWeb</code> (31 tipos) contiene: <ul><li>Cuentas, servicios, medidores, órdenes, presupuestos, ventas, transacciones, imágenes de ruta e incidentes: <code>CUENTAS_*</code>.</li><li>Usuarios y módulos: <code>USERS</code>, <code>MODULOS</code>.</li><li>Logos de factura y novedades: <code>WEB_Logos_Facturas</code>, <code>WEB_Novedades</code>.</li></ul></li></ul><p><strong>Alta de servicio desde el portal</strong> [P]</p><ul><li>Marca &quot;Alta desde CoopOnline&quot; en la ficha del servicio.</li></ul><p><strong>Registro de uso</strong> [T]</p><ul><li><code>WEB_LOG</code>.</li></ul><h3 id="funciones-esperadas-en-el-sistema-nuevo-i" tabindex="-1">Funciones esperadas en el sistema nuevo [I] <a class="header-anchor" href="#funciones-esperadas-en-el-sistema-nuevo-i" aria-label="Permalink to &quot;Funciones esperadas en el sistema nuevo [I]&quot;">​</a></h3><ul><li><strong>Cuentas y facturas:</strong> registro y vinculación de cuentas; consulta y descarga de facturas.</li><li><strong>Pagos:</strong> pago online y adhesión a débito automático y a factura digital.</li><li><strong>Consumos y lecturas:</strong> historial y gráfico de consumo; autolectura con foto.</li><li><strong>Gestiones:</strong> reclamos con seguimiento, trámites (alta, baja, cambio de titularidad) con adjuntos, turnos y notificaciones.</li></ul><hr><h2 id="_28-modulo-27-—-app-movil-de-campo-b" tabindex="-1">28. Módulo 27 — App móvil de campo (B) <a class="header-anchor" href="#_28-modulo-27-—-app-movil-de-campo-b" aria-label="Permalink to &quot;28. Módulo 27 — App móvil de campo (B)&quot;">​</a></h2><ul><li>El namespace <code>CapaDatos.PMovil</code> (39 tipos) cubre la toma de lecturas y la ejecución de órdenes [T].</li></ul><p><strong>Mejora:</strong> una sola app offline-first con perfiles de lecturista, técnico y cobrador.</p><hr><h2 id="_29-modulo-28-—-reportes-tableros-y-exportaciones-b" tabindex="-1">29. Módulo 28 — Reportes, tableros y exportaciones (B) <a class="header-anchor" href="#_29-modulo-28-—-reportes-tableros-y-exportaciones-b" aria-label="Permalink to &quot;29. Módulo 28 — Reportes, tableros y exportaciones (B)&quot;">​</a></h2><h3 id="funciones-m-t-9" tabindex="-1">Funciones [M][T] <a class="header-anchor" href="#funciones-m-t-9" aria-label="Permalink to &quot;Funciones [M][T]&quot;">​</a></h3><ul><li>Editor de Reportes, Informes Personalizados y Procesos Personalizados [M].</li><li>Tablas: <code>REPORTES</code>, <code>FORMULARIOS_PERSONALIZACIONES</code>.</li><li>Carpetas <code>Reportes</code> y <code>Reportes_Empresa</code>: reportes por cooperativa.</li><li>Exportador configurable de columnas: <code>EXPORTADOR</code>, <code>EXPORTADOR_COLUMNAS</code>.</li><li>Tablas expuestas a Power BI: <code>TABLAS_POWERBI</code>.</li><li>Tablero de Control [M].</li><li>Todos los listados del sistema tienen Exportar e Imprimir [P].</li></ul><h3 id="mejoras-propuestas-22" tabindex="-1">Mejoras propuestas <a class="header-anchor" href="#mejoras-propuestas-22" aria-label="Permalink to &quot;Mejoras propuestas&quot;">​</a></h3><ul><li><strong>Tableros por rol:</strong><ul><li>Gerencia: facturación, cobranza, mora y pérdidas.</li><li>Comercial.</li><li>Técnica.</li></ul></li><li><strong>Reportes estándar:</strong> padrón, emisión, cobranza por ente, morosidad por antigüedad, libro IVA y consumos por categoría.</li><li><strong>Exportación a Excel y CSV</strong> en cualquier grilla, más una API de datos para BI.</li></ul><hr><h2 id="_30-modulo-29-—-integraciones-externas-a-b" tabindex="-1">30. Módulo 29 — Integraciones externas (A/B) <a class="header-anchor" href="#_30-modulo-29-—-integraciones-externas-a-b" aria-label="Permalink to &quot;30. Módulo 29 — Integraciones externas (A/B)&quot;">​</a></h2><p>El detalle de cada integración (medio, frecuencia, dependencias y pendientes) está en <a href="./integraciones-fichas">integraciones-fichas.md</a>.</p><table tabindex="0"><thead><tr><th>Integración</th><th>Evidencia</th><th>Uso</th><th>Prioridad</th></tr></thead><tbody><tr><td>ARCA (ex AFIP): factura electrónica, CAEA, CESP, padrón</td><td>[P][M][T] <code>ELECTRONICA_*</code>, <code>CESPAFIP</code>, <code>EMPAFIP</code>, <code>ACTAFIP</code></td><td>Autorización de comprobantes</td><td>A</td></tr><tr><td>Rentas provincial (CVP, padrón IIBB)</td><td>[M][T] <code>CVPIIBB</code>, <code>IIBB_LUA</code></td><td>Validación provincial y percepciones</td><td>A</td></tr><tr><td>RED LINK</td><td>[P][T] <code>RED_LINK</code>, <code>DEUDARED</code></td><td>Cobranza por red</td><td>A</td></tr><tr><td>SIRO</td><td>[P][T] <code>SIRO_BASEDEUDA</code></td><td>Cobranza por red</td><td>A</td></tr><tr><td>Pagos360</td><td>[T] <code>PAGOS360*</code></td><td>Pago online</td><td>A</td></tr><tr><td>Débito automático bancario</td><td>[P][T] carpeta <code>Debitos</code></td><td>Débitos</td><td>A</td></tr><tr><td>EPEC</td><td>[T] <code>FACT_EPEC</code></td><td>Compra de energía y conciliación</td><td>B</td></tr><tr><td>ENARGAS</td><td>[M][T] <code>ENGAS_CANTMESES</code>, carpeta <code>ENARGAS</code></td><td>Información regulatoria de gas</td><td>B</td></tr><tr><td>ENACOM</td><td>[M]</td><td>Información de servicios TIC</td><td>C</td></tr><tr><td>INAES</td><td>[T] <code>CAT_INAES</code></td><td>Organismo de cooperativas</td><td>B</td></tr><tr><td>Interbanking</td><td>[T]</td><td>Pagos y transferencias</td><td>B</td></tr><tr><td>Telemedición</td><td>[M][T] <code>TELEMED_*</code></td><td>Lecturas remotas</td><td>B</td></tr><tr><td>MikroTik</td><td>[T]</td><td>Corte y habilitación de internet</td><td>C</td></tr><tr><td>Power BI</td><td>[T] <code>TABLAS_POWERBI</code></td><td>Análisis</td><td>C</td></tr><tr><td>WhatsApp, SMS, e-mail</td><td>[P][T]</td><td>Comunicaciones</td><td>B</td></tr><tr><td>Sistema contable externo</td><td>[T] <code>SISCONT</code></td><td>Exportación contable</td><td>C</td></tr><tr><td>Importación de padrones y DBF</td><td>[T] referencia a <code>NDbfReader</code>, carpeta <code>Importacion</code></td><td>Migraciones o archivos legados</td><td>B</td></tr></tbody></table><hr><h2 id="_31-procesos-transversales-clave-flujo-de-punta-a-punta" tabindex="-1">31. Procesos transversales clave (flujo de punta a punta) <a class="header-anchor" href="#_31-procesos-transversales-clave-flujo-de-punta-a-punta" aria-label="Permalink to &quot;31. Procesos transversales clave (flujo de punta a punta)&quot;">​</a></h2><ol><li><strong>Alta de un suministro:</strong><ol><li>Solicitud (ventanilla o portal).</li><li>Factibilidad técnica.</li><li>Presupuesto de conexión.</li><li>Orden de trabajo de conexión con colocación de medidor.</li><li>Servicio CONECTADO con categoría, ruta y grupo de factura.</li><li>Primera factura con el cargo de conexión.</li></ol></li><li><strong>Ciclo mensual de facturación:</strong><ol><li>Rutas de lectura (app o telemedición).</li><li>Validación de consumos.</li><li>Pre-facturación con el cuadro tarifario vigente.</li><li>Revisión de excepciones.</li><li>Emisión y autorización en ARCA.</li><li>Distribución (impresión, mail, portal).</li><li>Archivo de deuda a RED LINK y SIRO.</li></ol></li><li><strong>Cobro:</strong><ol><li>Caja, portal o ente.</li><li>Rendición e importación.</li><li>Imputación en la cuenta corriente.</li><li>Asiento contable.</li><li>Depósito y conciliación bancaria.</li></ol></li><li><strong>Mora:</strong><ol><li>Vencimientos.</li><li>Recargos por índice.</li><li>Candidatos.</li><li>Notificaciones de 1ª y 2ª instancia.</li><li>Orden de corte, o plan de pago.</li><li>Reconexión.</li></ol></li><li><strong>Cambio tarifario:</strong><ol><li>Resolución del regulador.</li><li>Nuevo cuadro con vigencia.</li><li>Simulación.</li><li>Aprobación.</li><li>Aplicación en la próxima facturación.</li></ol></li><li><strong>Compra de materiales:</strong><ol><li>Solicitud.</li><li>Cotización.</li><li>Orden de compra.</li><li>Recepción en stock.</li><li>Factura del proveedor.</li><li>Pago con retenciones.</li><li>Asiento.</li></ol></li></ol><hr><h2 id="_32-modelo-de-datos-de-referencia-resumen" tabindex="-1">32. Modelo de datos de referencia (resumen) <a class="header-anchor" href="#_32-modelo-de-datos-de-referencia-resumen" aria-label="Permalink to &quot;32. Modelo de datos de referencia (resumen)&quot;">​</a></h2><p>Agrupación de las 667 tablas de <code>CapaDatos</code> en dominios. El inventario completo está en <a href="./binarios/CapaDatos-inventario"><code>binarios/CapaDatos-inventario.md</code></a>.</p><table tabindex="0"><thead><tr><th>Dominio</th><th>Tablas principales</th></tr></thead><tbody><tr><td>Personas y cuentas</td><td><code>PERSONAS</code>, <code>SOCIOS</code>, <code>SUMSOC</code>, <code>SERSOC</code>, <code>RESPONSA</code>, <code>VINCULOS</code>, <code>PROPIEDA</code></td></tr><tr><td>Catálogo de servicios</td><td><code>SERVICIO</code>, <code>CLASESER</code>, <code>CATE_SER</code>, <code>CATTARIF</code>, <code>ESTASER</code>, <code>PROD_SER</code>, <code>CONEXION</code></td></tr><tr><td>Tarifas</td><td><code>CUADROS</code>, <code>HIS_CATTARIF</code>, <code>HIS_CATE_SER</code>, <code>HIS_IMPUESTO</code>, <code>HIS_CARGOS_ADICIONALES</code>, <code>IMPUESTO</code>, <code>CARGOS_ADICIONALES</code></td></tr><tr><td>Medición</td><td><code>MEDSOC</code>, <code>HIS_MEDSOC</code>, <code>MARMED</code>, <code>TIPMED</code>, <code>CONS_SER</code>, <code>TELEMEDICION</code>, <code>CONNRUTA</code></td></tr><tr><td>Facturación</td><td><code>FACTURAS</code>, <code>ITEMSFAC</code>, <code>FACTMES</code>, <code>TALONFAC</code>, <code>PTOVENTA</code>, <code>TIP_COMP</code>, <code>ELECTRONICA_*</code>, <code>ANUFAC</code></td></tr><tr><td>Cuenta corriente y cobranza</td><td><code>DEUDAVTA</code>, <code>PAG_SOC</code>, <code>IT_PAGSO</code>, <code>CAJAS</code>, <code>FORMAPA</code>, <code>ENTIDADES</code>, <code>RED_LINK</code>, <code>SIRO_BASEDEUDA</code>, <code>PAGOS360</code></td></tr><tr><td>Mora y financiación</td><td><code>TABMORA</code>, <code>INDICESMORA</code>, <code>MORATAS</code>, <code>EXC_MORA</code>, <code>INSTANCI</code>, <code>NOTIFICA</code>, <code>PPAGOS</code>, <code>PLAN_CUO</code></td></tr><tr><td>Técnica y redes</td><td><code>TECNICA</code>, <code>RECLAMOS</code>, <code>FACTIBIL</code>, <code>OBRAS</code>, <code>CUADRI</code>, <code>REDES_*</code></td></tr><tr><td>Compras y stock</td><td><code>PROVEED</code>, <code>SAPROV</code>, <code>SCOTIZ</code>, <code>OCOMPRA</code>, <code>RECEPCIONES</code>, <code>COMP_COM</code>, <code>DEPOSITO</code>, <code>BIENES_USO</code>, <code>ORDEFAB</code></td></tr><tr><td>Tesorería</td><td><code>BANCOS</code>, <code>VALORES</code>, <code>CHEQUERAS</code>, <code>TESORE</code>, <code>RESBAN</code>, <code>INTERBANKING</code></td></tr><tr><td>Contabilidad</td><td><code>CTPLAN</code>, <code>CTASIEN</code>, <code>CTITASIE</code>, <code>CTEJER</code>, <code>CTSECCION</code></td></tr><tr><td>Sueldos</td><td><code>SU_EMPLEADOS</code>, <code>SU_SUELDOS</code>, <code>SU_CONCEPTOS</code>, <code>SU_VARIABLES</code></td></tr><tr><td>Atención</td><td><code>TICKETS*</code>, <code>TURNOS</code>, <code>LLAMADAS</code>, <code>ENCUESTAS</code>, <code>PLANTILLA_WSP</code></td></tr><tr><td>Seguridad</td><td><code>USERS</code>, <code>PERFILES</code>, <code>MENUSYS</code>, <code>AUDITORIA</code>, <code>AUTORIZACIONES</code></td></tr></tbody></table><p><strong>Patrones del modelo de Procoop a tener en cuenta en el diseño nuevo:</strong></p><ul><li><strong>Anulaciones en tablas espejo</strong> (<code>ANUFAC</code>, <code>ANUPAG_SOC</code>). Mejora: estado más documento de reversión.</li><li><strong>Históricos en tablas separadas</strong> (<code>HIS_*</code>, <code>*_HST</code>). Mejora: vigencias (fecha desde/hasta) en el mismo modelo.</li><li><strong>Campos configurables en tablas <code>*_EXTRAS</code>.</strong> Mejora: atributos configurables tipados.</li></ul><hr><h2 id="_33-propuesta-de-etapas-a-validar" tabindex="-1">33. Propuesta de etapas, a validar <a class="header-anchor" href="#_33-propuesta-de-etapas-a-validar" aria-label="Permalink to &quot;33. Propuesta de etapas, a validar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Etapa</th><th>Módulos</th><th>Hito</th></tr></thead><tbody><tr><td>1 — Núcleo comercial</td><td>1, 2, 3, 4, 5, 6, 7, 8, 9</td><td>Facturar en paralelo con Procoop y comparar los resultados factura por factura</td></tr><tr><td>2 — Cobro y mora</td><td>10, 11, 29 (ARCA, RED LINK, SIRO, Pagos360, débitos)</td><td>Paralelo completo desde el 1/3/2027</td></tr><tr><td>3 — Operación</td><td>12, 13, 14, 21, 26, 27, 28</td><td>Atención y técnica fuera de Procoop</td></tr><tr><td>4 — Administración</td><td>16, 17, 18, 19</td><td>By pass de Procoop el 1/7/2027</td></tr><tr><td>5 — Complementarios</td><td>15, 20, 22, 23, 24, 25</td><td>Según la necesidad de cada cooperativa</td></tr></tbody></table><p><strong>Nota:</strong> el plan del proyecto pone Contabilidad primero. Hay que decidir si la etapa 4 se adelanta o si se contabiliza vía exportación durante el paralelo.</p><p><strong>Criterio de aceptación del paralelo:</strong> para el mismo período y el mismo padrón, cada factura del sistema nuevo coincide con la de Procoop en cantidades, importes por concepto, impuestos y vencimientos. Toda diferencia debe estar explicada.</p><hr><h2 id="_34-pendientes-para-cerrar-la-definicion" tabindex="-1">34. Pendientes para cerrar la definición <a class="header-anchor" href="#_34-pendientes-para-cerrar-la-definicion" aria-label="Permalink to &quot;34. Pendientes para cerrar la definición&quot;">​</a></h2><ol><li><strong>Lógica de cálculo:</strong> descompilar el ejecutable principal y las DLL de negocio. Pedir la carpeta <code>SISTEMA_PRD</code> completa. En particular, el detalle de los cuadros tarifarios, que solo se ve en modo &quot;Modificar&quot;.</li><li><strong>Datos reales de parametrización:</strong> consultas de solo lectura a la base sobre <code>CUADROS</code> / <code>HIS_*</code>, <code>IMPUESTO</code>, <code>CATE_SER</code>, <code>CONJUNTO</code>, <code>GRUPOS_FACTURA</code>, <code>TABMORA</code> y <code>TRAMASREC</code>.</li><li><strong>Pantallas no abiertas:</strong><ul><li>Cobranza local y apertura de caja (abrir una caja graba datos).</li><li>Facturación masiva.</li><li>Telemed.</li><li>Financiaciones.</li><li>Órdenes de trabajo.</li><li>Compras.</li><li>Contabilidad.</li></ul></li><li><strong>Validar con la cooperativa piloto</strong> qué módulos usan hoy. La DEMO muestra módulos habilitados, pero no necesariamente usados: vivienda, ambulancias y telefonía.</li><li><strong>Formatos de los archivos</strong> de RED LINK, SIRO, débitos y EPEC. Pedir ejemplos anonimizados.</li></ol>`,516)])])}const m=o(c,[["render",r]]);export{A as __pageData,m as default};
